"""Typed public exceptions for structa-maestro (contracts/python-api-and-cli.md Section 1.2)."""

from __future__ import annotations


class StructaMaestroError(Exception):
    """Base exception for configuration, schema definition, and contract deserialization errors."""


class SchemaDefinitionError(StructaMaestroError):
    """Raised before extraction when a user-supplied schema is invalid or unsupported."""


class ConfigurationError(StructaMaestroError):
    """Raised when engine, limits, or strategy configuration is invalid."""


class ContractDeserializationError(StructaMaestroError):
    """Raised when deserializing malformed or unsupported canonical output contract payloads."""

"""Configuration models, resource limits, secret masking, and privacy-safe logging helpers."""

from __future__ import annotations

import logging
import re
from collections.abc import Iterable
from dataclasses import dataclass

from structa_maestro.exceptions import ConfigurationError

_DEFAULT_MAX_FILE_BYTES = 25 * 1024 * 1024  # 25 MB
_DEFAULT_MAX_DECOMPRESSED_BYTES = 50 * 1024 * 1024  # 50 MB
_DEFAULT_MAX_PAGES = 200

_SECRET_PATTERNS: tuple[re.Pattern[str], ...] = (
    re.compile(r"(?i)(bearer\s+)[A-Za-z0-9._\-+/=]{8,}"),
    re.compile(r"\bsk-[A-Za-z0-9_\-]{8,}\b"),
    re.compile(r"(?i)(api[_-]?key\s*[:=]\s*['\"]?)([^\s'\",;}{]{6,})"),
    re.compile(r"(?i)(authorization\s*[:=]\s*['\"]?)([^\s'\",;}{]{6,})"),
)


@dataclass(frozen=True, slots=True)
class DocumentLimits:
    """Configurable safety limits enforced during document input and parsing.

    Canonical fields per specs/001-structured-extraction-mvp/data-model.md Section 2.1:
    - DocumentLimits.max_file_bytes
    - DocumentLimits.max_decompressed_bytes
    - DocumentLimits.max_pages
    """

    max_file_bytes: int = _DEFAULT_MAX_FILE_BYTES
    max_decompressed_bytes: int = _DEFAULT_MAX_DECOMPRESSED_BYTES
    max_pages: int = _DEFAULT_MAX_PAGES

    def __post_init__(self) -> None:
        if isinstance(self.max_file_bytes, bool) or self.max_file_bytes <= 0:
            raise ConfigurationError("DocumentLimits.max_file_bytes must be a positive integer.")
        if isinstance(self.max_decompressed_bytes, bool) or self.max_decompressed_bytes <= 0:
            raise ConfigurationError(
                "DocumentLimits.max_decompressed_bytes must be a positive integer."
            )
        if isinstance(self.max_pages, bool) or self.max_pages <= 0:
            raise ConfigurationError("DocumentLimits.max_pages must be a positive integer.")


class SecretValue:
    """Redacted container for API keys and credentials preventing accidental leakage."""

    __slots__ = ("_value",)

    def __init__(self, value: str) -> None:
        if not isinstance(value, str) or not value.strip():
            raise ConfigurationError("SecretValue requires a non-empty string.")
        self._value = value

    def get_secret_value(self) -> str:
        """Return the underlying raw secret value for authorized internal use."""
        return self._value

    def __repr__(self) -> str:
        return "SecretValue('***')"

    def __str__(self) -> str:
        return "***"

    def __eq__(self, other: object) -> bool:
        if isinstance(other, SecretValue):
            return self._value == other._value
        return False

    def __hash__(self) -> int:
        return hash(self._value)


def sanitize_message(
    message: str,
    *,
    secrets: Iterable[str] = (),
    max_length: int = 500,
) -> str:
    """Scrub known secrets and credential patterns from diagnostic messages."""
    sanitized = message
    for secret in secrets:
        if secret:
            sanitized = sanitized.replace(secret, "[REDACTED]")
    sanitized = _SECRET_PATTERNS[0].sub(r"\1[REDACTED]", sanitized)
    sanitized = _SECRET_PATTERNS[1].sub("[REDACTED]", sanitized)
    sanitized = _SECRET_PATTERNS[2].sub(r"\1[REDACTED]", sanitized)
    sanitized = _SECRET_PATTERNS[3].sub(r"\1[REDACTED]", sanitized)
    if len(sanitized) > max_length:
        sanitized = sanitized[: max_length - 3] + "..."
    return sanitized


def get_logger(name: str) -> logging.Logger:
    """Return a library logger configured with a NullHandler (no default document logging)."""
    root = logging.getLogger("structa_maestro")
    if not root.handlers:
        root.addHandler(logging.NullHandler())
    return logging.getLogger(name)

"""Canonical Output Record Contract v1.0 models (data-model.md Sections 2.2 & 3.1-3.8)."""

from __future__ import annotations

from typing import Any, Literal
from uuid import uuid4

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator

from structa_maestro.contracts.enums import (
    EvidenceRelationship,
    FieldPresence,
    FieldType,
    IssueSeverity,
    PipelineStage,
    ProcessingStatus,
    ValidationStatus,
)

CONTRACT_VERSION: Literal["1.0"] = "1.0"


class _ContractModel(BaseModel):
    model_config = ConfigDict(
        frozen=True,
        extra="forbid",
        populate_by_name=True,
        ser_json_timedelta="iso8601",
    )


class SourceMetadata(_ContractModel):
    """Public source document identity (data-model.md Section 2.2)."""

    document_id: str = Field(min_length=1)
    filename: str | None = None
    media_type: str | None = None


class SchemaMetadata(_ContractModel):
    """Public schema identity (data-model.md Section 3.8)."""

    schema_id: str = Field(min_length=1)
    schema_version: str = Field(min_length=1)


class SourceLocation(_ContractModel):
    """Optional granular location within the originating document (data-model.md Section 3.1)."""

    page: int | None = Field(default=None, ge=1)
    paragraph: int | None = Field(default=None, ge=1)
    line_start: int | None = Field(default=None, ge=1)
    line_end: int | None = Field(default=None, ge=1)
    char_start: int | None = Field(default=None, ge=0)
    char_end: int | None = Field(default=None, ge=0)
    section: str | None = None

    @model_validator(mode="after")
    def _check_spans(self) -> SourceLocation:
        if (
            self.line_start is not None
            and self.line_end is not None
            and self.line_end < self.line_start
        ):
            raise ValueError("SourceLocation.line_end must be >= line_start.")
        if (
            self.char_start is not None
            and self.char_end is not None
            and self.char_end < self.char_start
        ):
            raise ValueError("SourceLocation.char_end must be >= char_start.")
        return self


class ProvenanceEvidence(_ContractModel):
    """Supporting source evidence linked to an extracted field (data-model.md Section 3.2)."""

    source_document_id: str = Field(min_length=1)
    location: SourceLocation | None = None
    evidence: str
    relationship: EvidenceRelationship
    truncated: bool = False


class ConfidenceAssessment(_ContractModel):
    """Explicit reliability assessment kept independent of validation (data-model.md Section 3.3)."""

    value: float | None = None
    scale: str = Field(default="0-1", min_length=1)
    method: str = Field(default="extraction-assessment", min_length=1)
    calibrated: bool = False

    @model_validator(mode="after")
    def _check_value_bounds(self) -> ConfidenceAssessment:
        if self.value is not None and self.scale == "0-1" and not (0.0 <= self.value <= 1.0):
            raise ValueError("ConfidenceAssessment.value must be within [0.0, 1.0] for scale 0-1.")
        return self


class DiagnosticIssue(_ContractModel):
    """Structured, privacy-safe error or warning (data-model.md Section 3.4)."""

    code: str = Field(min_length=1)
    severity: IssueSeverity
    stage: PipelineStage
    message: str = Field(min_length=1)
    record_id: str | None = None
    field_path: str | None = None
    expected: str | None = None
    actual: str | None = None


class ValidationOutcome(_ContractModel):
    """Independent structural and constraint validation result (data-model.md Section 3.5)."""

    status: ValidationStatus
    errors: list[DiagnosticIssue] = Field(default_factory=list)

    @model_validator(mode="after")
    def _check_validation_errors(self) -> ValidationOutcome:
        for err in self.errors:
            if err.severity != IssueSeverity.ERROR or err.stage != PipelineStage.VALIDATION:
                raise ValueError(
                    "ValidationOutcome.errors must contain only validation-stage errors."
                )
        if self.status != ValidationStatus.INVALID and self.errors:
            raise ValueError("ValidationOutcome.errors must be empty unless status is 'invalid'.")
        return self


class ExtractedField(_ContractModel):
    """Single extracted field with independent quality dimensions (data-model.md Section 3.6)."""

    presence: FieldPresence
    value: Any = None
    value_type: FieldType | None = None
    confidence: ConfidenceAssessment | None = None
    provenance: list[ProvenanceEvidence] = Field(default_factory=list)
    validation: ValidationOutcome
    errors: list[DiagnosticIssue] = Field(default_factory=list)
    warnings: list[DiagnosticIssue] = Field(default_factory=list)

    @model_validator(mode="after")
    def _check_presence_value(self) -> ExtractedField:
        if self.presence == FieldPresence.MISSING and self.value is not None:
            raise ValueError("ExtractedField.value must be None when presence is 'missing'.")
        return self


class ExtractedRecord(_ContractModel):
    """Single bounded structured record within an extraction result (data-model.md Section 3.7)."""

    record_id: str = Field(min_length=1)
    status: ProcessingStatus
    fields: dict[str, ExtractedField] = Field(default_factory=dict)
    validation: ValidationOutcome
    errors: list[DiagnosticIssue] = Field(default_factory=list)
    warnings: list[DiagnosticIssue] = Field(default_factory=list)


class ExtractionResult(_ContractModel):
    """Top-level Canonical Output Record Contract v1.0 (data-model.md Section 3.8).

    Uses ``schema_metadata`` with ``alias="schema"`` so canonical JSON uses the exact
    ``"schema"`` key without shadowing Pydantic v2's deprecated ``BaseModel.schema()``.
    """

    contract_version: Literal["1.0"] = CONTRACT_VERSION
    extraction_id: str = Field(default_factory=lambda: str(uuid4()), min_length=1)
    status: ProcessingStatus
    source: SourceMetadata | None = None
    schema_metadata: SchemaMetadata = Field(alias="schema")
    records: list[ExtractedRecord] = Field(default_factory=list)
    validation: ValidationOutcome
    errors: list[DiagnosticIssue] = Field(default_factory=list)
    warnings: list[DiagnosticIssue] = Field(default_factory=list)

    @field_validator("records")
    @classmethod
    def _check_unique_record_ids(cls, value: list[ExtractedRecord]) -> list[ExtractedRecord]:
        seen: set[str] = set()
        for rec in value:
            if rec.record_id in seen:
                raise ValueError(f"Duplicate record_id detected: {rec.record_id!r}")
            seen.add(rec.record_id)
        return value

    @model_validator(mode="after")
    def _check_provenance_source_binding(self) -> ExtractionResult:
        if self.source is not None:
            expected_doc_id = self.source.document_id
            for record in self.records:
                for field_name, extracted_field in record.fields.items():
                    for ev in extracted_field.provenance:
                        if ev.source_document_id != expected_doc_id:
                            raise ValueError(
                                f"Provenance for field {field_name!r} references foreign "
                                f"document_id {ev.source_document_id!r} != {expected_doc_id!r}."
                            )
        return self

    def to_dict(self) -> dict[str, Any]:
        """Serialize this result to a canonical JSON-compatible dictionary."""
        from structa_maestro.contracts.serialization import serialize_result_to_dict

        return serialize_result_to_dict(self)

    def to_json(self, *, indent: int | None = None) -> str:
        """Serialize this result to canonical UTF-8 JSON."""
        from structa_maestro.contracts.serialization import serialize_result_to_json

        return serialize_result_to_json(self, indent=indent)

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ExtractionResult:
        """Strictly deserialize a canonical dictionary into an ExtractionResult."""
        from structa_maestro.contracts.serialization import deserialize_result_from_dict

        return deserialize_result_from_dict(data)

    @classmethod
    def from_json(cls, raw_json: str) -> ExtractionResult:
        """Strictly deserialize canonical JSON into an ExtractionResult."""
        from structa_maestro.contracts.serialization import deserialize_result_from_json

        return deserialize_result_from_json(raw_json)

"""Lossless JSON/dict serialization and strict deserialization for Canonical Output Contract v1.0."""

from __future__ import annotations

import json
from datetime import date, datetime
from decimal import Decimal, InvalidOperation
from typing import Any

from pydantic import ValidationError as PydanticValidationError

from structa_maestro.contracts.enums import FieldType
from structa_maestro.contracts.models import CONTRACT_VERSION, ExtractionResult
from structa_maestro.exceptions import ContractDeserializationError

_REQUIRED_TOP_LEVEL_KEYS = frozenset(
    {
        "contract_version",
        "extraction_id",
        "status",
        "source",
        "schema",
        "records",
        "validation",
        "errors",
        "warnings",
    }
)


def _encode_json_value(value: Any) -> Any:
    """Recursively convert Python scalar types into lossless JSON-native values."""
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, Decimal):
        return str(value)
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, date):
        return value.isoformat()
    if isinstance(value, list):
        return [_encode_json_value(item) for item in value]
    if isinstance(value, tuple):
        return [_encode_json_value(item) for item in value]
    if isinstance(value, dict):
        return {str(k): _encode_json_value(v) for k, v in value.items()}
    return str(value)


def _restore_typed_field_value(value: Any, value_type: str | None) -> Any:
    """Restore Decimal and date Python types on deserialization when value_type is declared."""
    if value is None or value_type is None:
        return value
    if value_type == FieldType.DECIMAL.value:
        if isinstance(value, Decimal):
            return value
        if isinstance(value, (str, int)) and not isinstance(value, bool):
            try:
                return Decimal(str(value))
            except InvalidOperation:
                return value
        if isinstance(value, float):
            return Decimal(str(value))
        return value
    if value_type == FieldType.DATE.value:
        if isinstance(value, date) and not isinstance(value, datetime):
            return value
        if isinstance(value, str):
            try:
                return date.fromisoformat(value)
            except ValueError:
                return value
        return value
    return value


def serialize_result_to_dict(result: ExtractionResult) -> dict[str, Any]:
    """Convert an ExtractionResult to a canonical JSON-compatible dictionary."""
    raw = result.model_dump(mode="python", by_alias=True)
    # Encode enums & special scalar values cleanly for JSON schema compliance
    encoded = _normalize_for_json_dict(raw)
    assert isinstance(encoded, dict)
    return encoded


def _normalize_for_json_dict(obj: Any) -> Any:
    if obj is None or isinstance(obj, (bool, int, float, str)):
        return obj
    if isinstance(obj, Decimal):
        return str(obj)
    if isinstance(obj, datetime):
        return obj.isoformat()
    if isinstance(obj, date):
        return obj.isoformat()
    if isinstance(obj, list):
        return [_normalize_for_json_dict(item) for item in obj]
    if isinstance(obj, dict):
        return {str(k): _normalize_for_json_dict(v) for k, v in obj.items()}
    return _encode_json_value(obj)


def serialize_result_to_json(result: ExtractionResult, *, indent: int | None = None) -> str:
    """Serialize an ExtractionResult to canonical UTF-8 JSON preserving exact field meaning."""
    payload = serialize_result_to_dict(result)
    return json.dumps(payload, ensure_ascii=False, indent=indent, allow_nan=False)


def deserialize_result_from_dict(data: Any) -> ExtractionResult:
    """Strictly deserialize and validate a canonical dictionary into ExtractionResult."""
    if not isinstance(data, dict):
        raise ContractDeserializationError("Canonical result payload must be a JSON object.")

    missing = _REQUIRED_TOP_LEVEL_KEYS - set(data.keys())
    if missing:
        missing_str = ", ".join(sorted(missing))
        raise ContractDeserializationError(
            f"Missing required canonical contract properties: {missing_str}"
        )

    version = data.get("contract_version")
    if version != CONTRACT_VERSION:
        raise ContractDeserializationError(
            f"Unsupported contract_version {version!r}; expected {CONTRACT_VERSION!r}."
        )

    # Restore typed scalar values (Decimal / date) on fields before Pydantic validation
    prepared = dict(data)
    raw_records = prepared.get("records")
    if isinstance(raw_records, list):
        restored_records: list[Any] = []
        for rec in raw_records:
            if isinstance(rec, dict) and isinstance(rec.get("fields"), dict):
                new_fields: dict[str, Any] = {}
                for fname, fdata in rec["fields"].items():
                    if isinstance(fdata, dict):
                        fcopy = dict(fdata)
                        fcopy["value"] = _restore_typed_field_value(
                            fcopy.get("value"), fcopy.get("value_type")
                        )
                        new_fields[fname] = fcopy
                    else:
                        new_fields[fname] = fdata
                rec_copy = dict(rec)
                rec_copy["fields"] = new_fields
                restored_records.append(rec_copy)
            else:
                restored_records.append(rec)
        prepared["records"] = restored_records

    try:
        return ExtractionResult.model_validate(prepared)
    except PydanticValidationError as exc:
        raise ContractDeserializationError(
            f"Canonical result failed contract validation: {exc.error_count()} error(s)."
        ) from exc


def deserialize_result_from_json(raw_json: str) -> ExtractionResult:
    """Strictly parse and deserialize canonical JSON into ExtractionResult."""
    if not isinstance(raw_json, str) or not raw_json.strip():
        raise ContractDeserializationError("Canonical JSON input must be a non-empty string.")
    try:
        parsed = json.loads(raw_json)
    except json.JSONDecodeError as exc:
        raise ContractDeserializationError(
            f"Invalid JSON syntax in canonical result at line {exc.lineno}, col {exc.colno}."
        ) from exc
    return deserialize_result_from_dict(parsed)

"""User-defined ExtractionSchema domain models (data-model.md Section 2.4)."""

from __future__ import annotations

import re
from collections.abc import Mapping
from dataclasses import dataclass, field
from decimal import Decimal
from pathlib import Path
from typing import Any

from structa_maestro.contracts.enums import ExtractionCardinality, FieldType
from structa_maestro.exceptions import SchemaDefinitionError

_NUMERIC_TYPES = frozenset({FieldType.INTEGER, FieldType.DECIMAL})
_DEFAULT_MAX_DEPTH = 16


@dataclass(frozen=True, slots=True)
class FieldConstraints:
    """Optional single-field validation constraints (data-model.md Section 2.4)."""

    min_value: int | Decimal | None = None
    max_value: int | Decimal | None = None
    min_length: int | None = None
    max_length: int | None = None
    min_items: int | None = None
    max_items: int | None = None
    pattern: str | None = None
    allowed_values: tuple[Any, ...] | None = None

    def __post_init__(self) -> None:
        if isinstance(self.min_value, bool) or isinstance(self.max_value, bool):
            raise SchemaDefinitionError("min_value/max_value cannot be booleans.")
        if (
            self.min_value is not None
            and self.max_value is not None
            and self.min_value > self.max_value
        ):
            raise SchemaDefinitionError(
                f"Conflicting numeric bounds: min_value ({self.min_value}) > max_value ({self.max_value})."
            )
        if self.min_length is not None and (
            isinstance(self.min_length, bool) or self.min_length < 0
        ):
            raise SchemaDefinitionError("min_length must be an integer >= 0.")
        if self.max_length is not None and (
            isinstance(self.max_length, bool) or self.max_length < 0
        ):
            raise SchemaDefinitionError("max_length must be an integer >= 0.")
        if (
            self.min_length is not None
            and self.max_length is not None
            and self.min_length > self.max_length
        ):
            raise SchemaDefinitionError(
                f"Conflicting length bounds: min_length ({self.min_length}) > max_length ({self.max_length})."
            )
        if self.min_items is not None and (isinstance(self.min_items, bool) or self.min_items < 0):
            raise SchemaDefinitionError("min_items must be an integer >= 0.")
        if self.max_items is not None and (isinstance(self.max_items, bool) or self.max_items < 0):
            raise SchemaDefinitionError("max_items must be an integer >= 0.")
        if (
            self.min_items is not None
            and self.max_items is not None
            and self.min_items > self.max_items
        ):
            raise SchemaDefinitionError(
                f"Conflicting array bounds: min_items ({self.min_items}) > max_items ({self.max_items})."
            )
        if self.pattern is not None:
            if not isinstance(self.pattern, str):
                raise SchemaDefinitionError("pattern constraint must be a string.")
            try:
                re.compile(self.pattern)
            except re.error as exc:
                raise SchemaDefinitionError(f"Invalid regex pattern constraint: {exc}") from exc
        if self.allowed_values is not None and len(self.allowed_values) == 0:
            raise SchemaDefinitionError("allowed_values cannot be an empty collection.")


@dataclass(frozen=True, slots=True)
class FieldSpec:
    """Definition of a single target field in an ExtractionSchema (data-model.md Section 2.4)."""

    name: str
    field_type: FieldType
    required: bool = True
    nullable: bool = False
    description: str | None = None
    constraints: FieldConstraints = field(default_factory=FieldConstraints)
    properties: dict[str, FieldSpec] | None = None
    items: FieldSpec | None = None
    allow_additional_fields: bool = False

    def __post_init__(self) -> None:
        if not isinstance(self.name, str) or not self.name.strip():
            raise SchemaDefinitionError("FieldSpec.name must be a non-empty string.")
        if not isinstance(self.field_type, FieldType):
            raise SchemaDefinitionError(f"Unsupported field_type: {self.field_type!r}")
        if not isinstance(self.required, bool):
            raise SchemaDefinitionError("FieldSpec.required must be a boolean.")
        if not isinstance(self.nullable, bool):
            raise SchemaDefinitionError("FieldSpec.nullable must be a boolean.")
        if not isinstance(self.allow_additional_fields, bool):
            raise SchemaDefinitionError("FieldSpec.allow_additional_fields must be a boolean.")

        c = self.constraints
        if (c.min_value is not None or c.max_value is not None) and (
            self.field_type not in _NUMERIC_TYPES
        ):
            raise SchemaDefinitionError(
                f"Numeric min_value/max_value constraints are incompatible with {self.field_type.value!r}."
            )
        if (c.min_length is not None or c.max_length is not None or c.pattern is not None) and (
            self.field_type != FieldType.STRING
        ):
            raise SchemaDefinitionError(
                f"String constraints are incompatible with field type {self.field_type.value!r}."
            )
        if (c.min_items is not None or c.max_items is not None) and (
            self.field_type != FieldType.ARRAY
        ):
            raise SchemaDefinitionError(
                f"Array item count constraints are incompatible with {self.field_type.value!r}."
            )

        if self.field_type == FieldType.OBJECT:
            if not self.properties:
                raise SchemaDefinitionError(
                    f"Object field {self.name!r} must define non-empty properties."
                )
            for prop_key, prop_spec in self.properties.items():
                if prop_spec.name != prop_key:
                    raise SchemaDefinitionError(
                        f"Property key {prop_key!r} does not match FieldSpec.name {prop_spec.name!r}."
                    )
        elif self.properties is not None:
            raise SchemaDefinitionError(
                f"Non-object field {self.name!r} cannot define nested properties."
            )

        if self.field_type == FieldType.ARRAY:
            if self.items is None:
                raise SchemaDefinitionError(f"Array field {self.name!r} must define items.")
        elif self.items is not None:
            raise SchemaDefinitionError(f"Non-array field {self.name!r} cannot define items.")


@dataclass(frozen=True, slots=True)
class ExtractionSchema:
    """User-defined structured extraction schema (data-model.md Section 2.4)."""

    schema_id: str
    schema_version: str
    fields: dict[str, FieldSpec]
    cardinality: ExtractionCardinality = ExtractionCardinality.SINGLE
    allow_additional_fields: bool = False
    max_depth: int = _DEFAULT_MAX_DEPTH

    def __post_init__(self) -> None:
        if not isinstance(self.schema_id, str) or not self.schema_id.strip():
            raise SchemaDefinitionError("ExtractionSchema.schema_id must be a non-empty string.")
        if not isinstance(self.schema_version, str) or not self.schema_version.strip():
            raise SchemaDefinitionError(
                "ExtractionSchema.schema_version must be a non-empty string."
            )
        if not isinstance(self.cardinality, ExtractionCardinality):
            raise SchemaDefinitionError(f"Unsupported cardinality: {self.cardinality!r}")
        if not isinstance(self.allow_additional_fields, bool):
            raise SchemaDefinitionError("ExtractionSchema.allow_additional_fields must be boolean.")
        if isinstance(self.max_depth, bool) or self.max_depth < 1:
            raise SchemaDefinitionError("ExtractionSchema.max_depth must be an integer >= 1.")
        if not self.fields:
            raise SchemaDefinitionError("ExtractionSchema.fields must define at least one field.")

        for key, spec in self.fields.items():
            if spec.name != key:
                raise SchemaDefinitionError(
                    f"Schema field key {key!r} does not match FieldSpec.name {spec.name!r}."
                )
            _validate_depth(spec, depth=1, max_depth=self.max_depth, seen_ids=set())

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> ExtractionSchema:
        """Parse and validate a declarative dict or JSON Schema subset into ExtractionSchema."""
        from structa_maestro.schema.loader import load_schema_from_dict

        return load_schema_from_dict(data)

    @classmethod
    def from_json_file(cls, path: str | Path) -> ExtractionSchema:
        """Load and validate an ExtractionSchema from a JSON file."""
        from structa_maestro.schema.loader import load_schema_from_json_file

        return load_schema_from_json_file(path)


def _validate_depth(
    spec: FieldSpec,
    *,
    depth: int,
    max_depth: int,
    seen_ids: set[int],
) -> None:
    obj_id = id(spec)
    if obj_id in seen_ids:
        raise SchemaDefinitionError(f"Recursive/cyclic schema definition detected at {spec.name!r}.")
    if depth > max_depth:
        raise SchemaDefinitionError(
            f"Schema nesting depth at {spec.name!r} exceeds maximum allowed depth ({max_depth})."
        )
    next_seen = seen_ids | {obj_id}
    if spec.properties:
        for child in spec.properties.values():
            _validate_depth(child, depth=depth + 1, max_depth=max_depth, seen_ids=next_seen)
    if spec.items is not None:
        _validate_depth(spec.items, depth=depth + 1, max_depth=max_depth, seen_ids=next_seen)

"""Declarative dictionary and JSON Schema loader raising SchemaDefinitionError on invalid schemas."""

from __future__ import annotations

import json
from collections.abc import Mapping
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Any

from structa_maestro.contracts.enums import ExtractionCardinality, FieldType
from structa_maestro.exceptions import SchemaDefinitionError
from structa_maestro.schema.models import ExtractionSchema, FieldConstraints, FieldSpec

_MAX_SCHEMA_JSON_BYTES = 2 * 1024 * 1024  # 2 MB safety limit for schema files

_TYPE_ALIASES: dict[str, FieldType] = {
    "string": FieldType.STRING,
    "str": FieldType.STRING,
    "integer": FieldType.INTEGER,
    "int": FieldType.INTEGER,
    "decimal": FieldType.DECIMAL,
    "number": FieldType.DECIMAL,
    "boolean": FieldType.BOOLEAN,
    "bool": FieldType.BOOLEAN,
    "date": FieldType.DATE,
    "array": FieldType.ARRAY,
    "object": FieldType.OBJECT,
}

_ALLOWED_TOP_LEVEL_KEYS = frozenset(
    {
        "schema_id",
        "schema_version",
        "cardinality",
        "fields",
        "properties",
        "required",
        "allow_additional_fields",
        "additionalProperties",
        "max_depth",
        "title",
        "type",
        "$schema",
        "$id",
        "description",
    }
)

_ALLOWED_FIELD_KEYS = frozenset(
    {
        "type",
        "format",
        "required",
        "nullable",
        "description",
        "min_value",
        "max_value",
        "minimum",
        "maximum",
        "min_length",
        "max_length",
        "minLength",
        "maxLength",
        "min_items",
        "max_items",
        "minItems",
        "maxItems",
        "pattern",
        "allowed_values",
        "enum",
        "properties",
        "items",
        "allow_additional_fields",
        "additionalProperties",
        "default",
        "$ref",
    }
)


def _reject_duplicate_json_keys(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    obj: dict[str, Any] = {}
    for key, val in pairs:
        if key in obj:
            raise SchemaDefinitionError(f"Duplicate key detected in schema definition: {key!r}")
        obj[key] = val
    return obj


def _coerce_numeric_bound(raw: Any, field_type: FieldType, bound_name: str) -> int | Decimal:
    if isinstance(raw, bool):
        raise SchemaDefinitionError(f"{bound_name} cannot be a boolean.")
    if field_type == FieldType.INTEGER:
        if isinstance(raw, int):
            return raw
        raise SchemaDefinitionError(f"{bound_name} for integer field must be an int.")
    if isinstance(raw, (int, Decimal)):
        return raw
    if isinstance(raw, (float, str)):
        try:
            return Decimal(str(raw))
        except InvalidOperation as exc:
            raise SchemaDefinitionError(f"Invalid numeric {bound_name}: {raw!r}") from exc
    raise SchemaDefinitionError(f"Invalid numeric {bound_name}: {raw!r}")


def _parse_field_type(raw_field: Mapping[str, Any], field_name: str) -> tuple[FieldType, bool]:
    raw_type = raw_field.get("type")
    inferred_nullable = False

    if isinstance(raw_type, list):
        non_null = [t for t in raw_type if t != "null"]
        inferred_nullable = "null" in raw_type
        if len(non_null) != 1 or not isinstance(non_null[0], str):
            raise SchemaDefinitionError(
                f"Field {field_name!r} has unsupported union type: {raw_type!r}"
            )
        raw_type = non_null[0]

    if not isinstance(raw_type, str):
        raise SchemaDefinitionError(f"Field {field_name!r} must declare a valid string 'type'.")

    fmt = raw_field.get("format")
    if raw_type == "string" and fmt == "date":
        return FieldType.DATE, inferred_nullable

    mapped = _TYPE_ALIASES.get(raw_type.lower())
    if mapped is None:
        raise SchemaDefinitionError(
            f"Unsupported schema type {raw_type!r} for field {field_name!r}."
        )
    return mapped, inferred_nullable


def _parse_field_spec(
    name: str,
    raw: Any,
    *,
    required_override: bool | None = None,
    depth: int,
    max_depth: int,
) -> FieldSpec:
    if depth > max_depth:
        raise SchemaDefinitionError(
            f"Schema nesting depth at {name!r} exceeds maximum allowed depth ({max_depth})."
        )
    if not isinstance(raw, Mapping):
        raise SchemaDefinitionError(f"Field definition for {name!r} must be an object/mapping.")

    if "$ref" in raw:
        raise SchemaDefinitionError(
            f"Recursive or external '$ref' schema definitions are unsupported (field {name!r})."
        )

    unknown_keys = set(raw.keys()) - _ALLOWED_FIELD_KEYS
    if unknown_keys:
        raise SchemaDefinitionError(
            f"Unknown schema attributes on field {name!r}: {', '.join(sorted(unknown_keys))}"
        )

    field_type, inferred_nullable = _parse_field_type(raw, name)

    raw_required = raw.get("required")
    if field_type == FieldType.OBJECT and isinstance(raw_required, list):
        nested_required_names = set(raw_required)
        is_required = True if required_override is None else required_override
    else:
        nested_required_names = None
        if raw_required is None:
            is_required = True if required_override is None else required_override
        elif isinstance(raw_required, bool):
            is_required = raw_required
        else:
            raise SchemaDefinitionError(f"Field {name!r} 'required' attribute must be a boolean.")

    raw_nullable = raw.get("nullable")
    if raw_nullable is None:
        nullable = inferred_nullable
    elif isinstance(raw_nullable, bool):
        nullable = raw_nullable or inferred_nullable
    else:
        raise SchemaDefinitionError(f"Field {name!r} 'nullable' attribute must be a boolean.")

    description = raw.get("description")
    if description is not None and not isinstance(description, str):
        raise SchemaDefinitionError(f"Field {name!r} 'description' must be a string.")

    # Constraints
    raw_min_val = raw.get("min_value", raw.get("minimum"))
    raw_max_val = raw.get("max_value", raw.get("maximum"))
    min_value = (
        _coerce_numeric_bound(raw_min_val, field_type, "min_value")
        if raw_min_val is not None
        else None
    )
    max_value = (
        _coerce_numeric_bound(raw_max_val, field_type, "max_value")
        if raw_max_val is not None
        else None
    )
    min_length = raw.get("min_length", raw.get("minLength"))
    max_length = raw.get("max_length", raw.get("maxLength"))
    min_items = raw.get("min_items", raw.get("minItems"))
    max_items = raw.get("max_items", raw.get("maxItems"))
    pattern = raw.get("pattern")
    raw_allowed = raw.get("allowed_values", raw.get("enum"))
    allowed_values: tuple[Any, ...] | None = None
    if raw_allowed is not None:
        if not isinstance(raw_allowed, (list, tuple)):
            raise SchemaDefinitionError(
                f"Field {name!r} 'allowed_values'/'enum' must be a list or tuple."
            )
        allowed_values = tuple(raw_allowed)

    constraints = FieldConstraints(
        min_value=min_value,
        max_value=max_value,
        min_length=min_length,
        max_length=max_length,
        min_items=min_items,
        max_items=max_items,
        pattern=pattern,
        allowed_values=allowed_values,
    )

    # Nested properties (for object)
    parsed_properties: dict[str, FieldSpec] | None = None
    if "properties" in raw and raw["properties"] is not None:
        raw_props = raw["properties"]
        if not isinstance(raw_props, Mapping) or not raw_props:
            raise SchemaDefinitionError(
                f"Object field {name!r} must define a non-empty 'properties' mapping."
            )
        parsed_properties = {}
        for prop_name, prop_def in raw_props.items():
            req_override = (
                prop_name in nested_required_names if nested_required_names is not None else None
            )
            parsed_properties[prop_name] = _parse_field_spec(
                prop_name,
                prop_def,
                required_override=req_override,
                depth=depth + 1,
                max_depth=max_depth,
            )

    # Array items
    parsed_items: FieldSpec | None = None
    if "items" in raw and raw["items"] is not None:
        parsed_items = _parse_field_spec(
            f"{name}[]",
            raw["items"],
            required_override=True,
            depth=depth + 1,
            max_depth=max_depth,
        )

    raw_addl = raw.get("allow_additional_fields", raw.get("additionalProperties", False))
    if not isinstance(raw_addl, bool):
        raise SchemaDefinitionError(
            f"Field {name!r} 'allow_additional_fields'/'additionalProperties' must be a boolean."
        )

    return FieldSpec(
        name=name,
        field_type=field_type,
        required=is_required,
        nullable=nullable,
        description=description,
        constraints=constraints,
        properties=parsed_properties,
        items=parsed_items,
        allow_additional_fields=raw_addl,
    )


def load_schema_from_dict(data: Mapping[str, Any]) -> ExtractionSchema:
    """Parse and validate a declarative dict or JSON Schema subset into ExtractionSchema."""
    if not isinstance(data, Mapping) or not data:
        raise SchemaDefinitionError("Schema definition must be a non-empty mapping.")

    unknown_top = set(data.keys()) - _ALLOWED_TOP_LEVEL_KEYS
    if unknown_top:
        raise SchemaDefinitionError(
            f"Unknown top-level schema attributes: {', '.join(sorted(unknown_top))}"
        )

    schema_id = data.get("schema_id") or data.get("title") or data.get("$id")
    if not isinstance(schema_id, str) or not schema_id.strip():
        raise SchemaDefinitionError("Schema must specify a non-empty 'schema_id' (or 'title').")

    schema_version = data.get("schema_version", "1.0")
    if not isinstance(schema_version, str) or not schema_version.strip():
        raise SchemaDefinitionError("Schema 'schema_version' must be a non-empty string.")

    raw_card = data.get("cardinality", ExtractionCardinality.SINGLE.value)
    try:
        cardinality = ExtractionCardinality(raw_card)
    except ValueError as exc:
        raise SchemaDefinitionError(
            f"Unsupported schema cardinality {raw_card!r}; expected 'single' or 'multiple'."
        ) from exc

    raw_max_depth = data.get("max_depth", 16)
    if isinstance(raw_max_depth, bool) or not isinstance(raw_max_depth, int) or raw_max_depth < 1:
        raise SchemaDefinitionError("Schema 'max_depth' must be an integer >= 1.")

    raw_addl = data.get("allow_additional_fields", data.get("additionalProperties", False))
    if not isinstance(raw_addl, bool):
        raise SchemaDefinitionError(
            "Schema 'allow_additional_fields'/'additionalProperties' must be a boolean."
        )

    raw_fields = data.get("fields") if "fields" in data else data.get("properties")
    if not isinstance(raw_fields, Mapping) or not raw_fields:
        raise SchemaDefinitionError(
            "Schema must define a non-empty 'fields' (or 'properties') mapping."
        )

    top_required = data.get("required")
    top_required_set: set[str] | None = None
    if top_required is not None:
        if not isinstance(top_required, list) or not all(isinstance(x, str) for x in top_required):
            raise SchemaDefinitionError("Top-level 'required' must be a list of field names.")
        top_required_set = set(top_required)

    parsed_fields: dict[str, FieldSpec] = {}
    for fname, fdef in raw_fields.items():
        if not isinstance(fname, str) or not fname.strip():
            raise SchemaDefinitionError("Schema field names must be non-empty strings.")
        req_override = fname in top_required_set if top_required_set is not None else None
        parsed_fields[fname] = _parse_field_spec(
            fname,
            fdef,
            required_override=req_override,
            depth=1,
            max_depth=raw_max_depth,
        )

    return ExtractionSchema(
        schema_id=schema_id.strip(),
        schema_version=schema_version.strip(),
        fields=parsed_fields,
        cardinality=cardinality,
        allow_additional_fields=raw_addl,
        max_depth=raw_max_depth,
    )


def load_schema_from_json_file(path: str | Path) -> ExtractionSchema:
    """Load and validate an ExtractionSchema from a JSON file with duplicate-key rejection."""
    schema_path = Path(path)
    if not schema_path.exists():
        raise SchemaDefinitionError(f"Schema file not found: {schema_path.name}")
    if not schema_path.is_file():
        raise SchemaDefinitionError(f"Schema path is not a regular file: {schema_path.name}")
    if schema_path.stat().st_size > _MAX_SCHEMA_JSON_BYTES:
        raise SchemaDefinitionError(
            f"Schema file exceeds maximum allowed size ({_MAX_SCHEMA_JSON_BYTES} bytes)."
        )
    try:
        raw_text = schema_path.read_text(encoding="utf-8")
    except OSError as exc:
        raise SchemaDefinitionError(f"Unable to read schema file: {exc}") from exc

    try:
        parsed = json.loads(raw_text, object_pairs_hook=_reject_duplicate_json_keys)
    except json.JSONDecodeError as exc:
        raise SchemaDefinitionError(
            f"Invalid JSON syntax in schema file at line {exc.lineno}, col {exc.colno}."
        ) from exc

    if not isinstance(parsed, Mapping):
        raise SchemaDefinitionError("Schema JSON root must be an object.")
    return load_schema_from_dict(parsed)

