"""Multi-encoding TXT parser with line-number DocumentSegment tracking."""

from __future__ import annotations

from dataclasses import dataclass

from structa_maestro.config import DocumentLimits
from structa_maestro.contracts.enums import DocumentFormat, IssueSeverity, PipelineStage
from structa_maestro.contracts.models import DiagnosticIssue, SourceMetadata
from structa_maestro.documents.models import DocumentSegment, PreparedDocument
from structa_maestro.documents.normalization import normalize_document_text

_KNOWN_BINARY_SIGNATURES: tuple[bytes, ...] = (
    b"\x89PNG\r\n\x1a\n",
    b"\xff\xd8\xff",
    b"GIF87a",
    b"GIF89a",
    b"\x7fELF",
    b"MZ",
    b"\x1f\x8b\x08",
    b"Rar!",
    b"7z\xbc\xaf\x27\x1c",
    b"\x00\x00\x01\x00",
)


@dataclass(frozen=True, slots=True)
class ParseResult:
    """Outcome of a single document parser invocation."""

    document: PreparedDocument | None
    errors: tuple[DiagnosticIssue, ...] = ()
    warnings: tuple[DiagnosticIssue, ...] = ()


def _looks_binary(raw: bytes) -> bool:
    for sig in _KNOWN_BINARY_SIGNATURES:
        if raw.startswith(sig):
            return True
    # UTF-16 BOM legitimately contains null bytes
    if raw.startswith((b"\xff\xfe", b"\xfe\xff")):
        return False
    if b"\x00" in raw[:8192]:
        return True
    sample = raw[:4096]
    if not sample:
        return False
    non_text = sum(1 for b in sample if b < 9 or (13 < b < 32) or b == 127)
    return (non_text / len(sample)) > 0.25


def _decode_text_bytes(raw: bytes) -> str | None:
    if raw.startswith((b"\xff\xfe", b"\xfe\xff")):
        try:
            return raw.decode("utf-16")
        except UnicodeDecodeError:
            return None
    if raw.startswith(b"\xef\xbb\xbf"):
        try:
            return raw.decode("utf-8-sig")
        except UnicodeDecodeError:
            return None
    for encoding in ("utf-8", "cp1252", "latin-1"):
        try:
            return raw.decode(encoding)
        except UnicodeDecodeError:
            continue
    return None


def parse_txt_bytes(
    raw: bytes,
    source: SourceMetadata,
    limits: DocumentLimits,
) -> ParseResult:
    """Parse raw TXT bytes into a PreparedDocument with 1-indexed line DocumentSegments."""
    if len(raw) == 0:
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="empty_document",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message="Input TXT document is empty (zero bytes).",
                ),
            ),
        )

    if _looks_binary(raw):
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="unsupported_format",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message="Input file appears to contain binary data rather than plain text.",
                ),
            ),
        )

    decoded = _decode_text_bytes(raw)
    if decoded is None:
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="decoding_error",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message="Unable to decode TXT document with supported text encodings.",
                ),
            ),
        )

    normalized = normalize_document_text(decoded)
    if len(normalized.encode("utf-8")) > limits.max_decompressed_bytes:
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="resource_limit_exceeded",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message="Prepared TXT text exceeds configured max_decompressed_bytes limit.",
                ),
            ),
        )

    if not normalized.strip():
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="empty_document",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message="TXT document contains no extractable text (whitespace only).",
                ),
            ),
        )

    segments: list[DocumentSegment] = []
    offset = 0
    lines = normalized.split("\n")
    for idx, line in enumerate(lines, start=1):
        char_start = offset
        char_end = offset + len(line)
        segments.append(
            DocumentSegment(
                text=line,
                char_start=char_start,
                char_end=char_end,
                line_start=idx,
                line_end=idx,
            )
        )
        offset = char_end + 1  # account for '\n'

    return ParseResult(
        document=PreparedDocument(
            source=source,
            format=DocumentFormat.TXT,
            full_text=normalized,
            segments=tuple(segments),
            page_count=None,
        )
    )

"""Text-based PDF parser using pypdf with page limits, encryption, and image-only detection."""

from __future__ import annotations

import io

from pypdf import PdfReader
from pypdf.errors import PdfReadError

from structa_maestro.config import DocumentLimits
from structa_maestro.contracts.enums import DocumentFormat, IssueSeverity, PipelineStage
from structa_maestro.contracts.models import DiagnosticIssue, SourceMetadata
from structa_maestro.documents.models import DocumentSegment, PreparedDocument
from structa_maestro.documents.normalization import normalize_document_text
from structa_maestro.documents.txt_parser import ParseResult


def parse_pdf_bytes(
    raw: bytes,
    source: SourceMetadata,
    limits: DocumentLimits,
) -> ParseResult:
    """Parse raw text-based PDF bytes enforcing DocumentLimits.max_pages & max_decompressed_bytes."""
    if len(raw) == 0:
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="empty_document",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message="Input PDF document is empty (zero bytes).",
                ),
            ),
        )

    try:
        reader = PdfReader(io.BytesIO(raw), strict=False)
    except (PdfReadError, Exception):
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="corrupted_document",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message="PDF document is corrupted or unreadable.",
                ),
            ),
        )

    if reader.is_encrypted:
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="corrupted_document",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message="Encrypted PDF documents are not supported without prior decryption.",
                ),
            ),
        )

    try:
        page_count = len(reader.pages)
    except Exception:
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="corrupted_document",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message="Unable to read PDF page structure.",
                ),
            ),
        )

    if page_count == 0:
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="empty_document",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message="PDF document contains zero pages.",
                ),
            ),
        )

    if page_count > limits.max_pages:
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="resource_limit_exceeded",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message=(
                        f"PDF page count ({page_count}) exceeds configured "
                        f"max_pages limit ({limits.max_pages})."
                    ),
                ),
            ),
        )

    segments: list[DocumentSegment] = []
    full_parts: list[str] = []
    warnings: list[DiagnosticIssue] = []
    cumulative_bytes = 0
    offset = 0

    for page_num, page in enumerate(reader.pages, start=1):
        try:
            raw_page_text = page.extract_text() or ""
        except Exception:
            warnings.append(
                DiagnosticIssue(
                    code="partial_page_parse_failure",
                    severity=IssueSeverity.WARNING,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message=f"Failed to extract text from PDF page {page_num}.",
                )
            )
            raw_page_text = ""

        normalized = normalize_document_text(raw_page_text).strip()
        cumulative_bytes += len(normalized.encode("utf-8"))
        if cumulative_bytes > limits.max_decompressed_bytes:
            return ParseResult(
                document=None,
                errors=(
                    DiagnosticIssue(
                        code="resource_limit_exceeded",
                        severity=IssueSeverity.ERROR,
                        stage=PipelineStage.DOCUMENT_PROCESSING,
                        message="Extracted PDF text exceeds configured max_decompressed_bytes.",
                    ),
                ),
            )
        if normalized:
            if full_parts:
                offset += 2  # "\n\n" separator
            char_start = offset
            char_end = offset + len(normalized)
            segments.append(
                DocumentSegment(
                    text=normalized,
                    char_start=char_start,
                    char_end=char_end,
                    page=page_num,
                )
            )
            full_parts.append(normalized)
            offset = char_end

    full_text = "\n\n".join(full_parts)
    if not full_text.strip():
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="no_extractable_text",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message=(
                        "PDF contains no extractable text layer "
                        "(image-only or scanned PDFs require OCR, which is outside MVP scope)."
                    ),
                ),
            ),
            warnings=tuple(warnings),
        )

    return ParseResult(
        document=PreparedDocument(
            source=source,
            format=DocumentFormat.PDF,
            full_text=full_text,
            segments=tuple(segments),
            page_count=page_count,
        ),
        warnings=tuple(warnings),
    )

"""ZIP-bomb-guarded DOCX parser extracting paragraphs, headings, and table text."""

from __future__ import annotations

import io
import zipfile

import docx

from structa_maestro.config import DocumentLimits
from structa_maestro.contracts.enums import DocumentFormat, IssueSeverity, PipelineStage
from structa_maestro.contracts.models import DiagnosticIssue, SourceMetadata
from structa_maestro.documents.models import DocumentSegment, PreparedDocument
from structa_maestro.documents.normalization import normalize_document_text
from structa_maestro.documents.txt_parser import ParseResult


def parse_docx_bytes(
    raw: bytes,
    source: SourceMetadata,
    limits: DocumentLimits,
) -> ParseResult:
    """Parse raw DOCX bytes with pre-open ZIP-bomb and archive-integrity guards."""
    if len(raw) == 0:
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="empty_document",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message="Input DOCX document is empty (zero bytes).",
                ),
            ),
        )

    try:
        with zipfile.ZipFile(io.BytesIO(raw), "r") as zf:
            names = set(zf.namelist())
            if "word/document.xml" not in names:
                return ParseResult(
                    document=None,
                    errors=(
                        DiagnosticIssue(
                            code="unsupported_format",
                            severity=IssueSeverity.ERROR,
                            stage=PipelineStage.DOCUMENT_PROCESSING,
                            message="ZIP archive is not a valid DOCX container (missing word/document.xml).",
                        ),
                    ),
                )
            total_uncompressed = sum(info.file_size for info in zf.infolist())
            if total_uncompressed > limits.max_decompressed_bytes:
                return ParseResult(
                    document=None,
                    errors=(
                        DiagnosticIssue(
                            code="resource_limit_exceeded",
                            severity=IssueSeverity.ERROR,
                            stage=PipelineStage.DOCUMENT_PROCESSING,
                            message=(
                                "DOCX uncompressed archive size exceeds configured "
                                f"max_decompressed_bytes limit ({limits.max_decompressed_bytes})."
                            ),
                        ),
                    ),
                )
    except zipfile.BadZipFile:
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="corrupted_document",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message="DOCX container is corrupted or not a valid ZIP archive.",
                ),
            ),
        )
    except Exception:
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="corrupted_document",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message="Unable to inspect DOCX container safely.",
                ),
            ),
        )

    try:
        document = docx.Document(io.BytesIO(raw))
    except Exception:
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="corrupted_document",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message="DOCX document structure is corrupted or unreadable.",
                ),
            ),
        )

    segments: list[DocumentSegment] = []
    full_parts: list[str] = []
    current_heading: str | None = None
    paragraph_index = 0
    cumulative_bytes = 0
    offset = 0

    for para in document.paragraphs:
        text = normalize_document_text(para.text).strip()
        if not text:
            continue
        style_name = para.style.name if para.style is not None else ""
        if style_name and style_name.lower().startswith("heading"):
            current_heading = text
        paragraph_index += 1
        cumulative_bytes += len(text.encode("utf-8"))
        if cumulative_bytes > limits.max_decompressed_bytes:
            return ParseResult(
                document=None,
                errors=(
                    DiagnosticIssue(
                        code="resource_limit_exceeded",
                        severity=IssueSeverity.ERROR,
                        stage=PipelineStage.DOCUMENT_PROCESSING,
                        message="Extracted DOCX text exceeds configured max_decompressed_bytes.",
                    ),
                ),
            )
        if full_parts:
            offset += 1  # '\n'
        char_start = offset
        char_end = offset + len(text)
        segments.append(
            DocumentSegment(
                text=text,
                char_start=char_start,
                char_end=char_end,
                paragraph=paragraph_index,
                heading=current_heading,
            )
        )
        full_parts.append(text)
        offset = char_end

    for table in document.tables:
        for row in table.rows:
            row_cells = [normalize_document_text(c.text).strip() for c in row.cells]
            row_text = " | ".join(cell for cell in row_cells if cell)
            if not row_text:
                continue
            paragraph_index += 1
            cumulative_bytes += len(row_text.encode("utf-8"))
            if cumulative_bytes > limits.max_decompressed_bytes:
                return ParseResult(
                    document=None,
                    errors=(
                        DiagnosticIssue(
                            code="resource_limit_exceeded",
                            severity=IssueSeverity.ERROR,
                            stage=PipelineStage.DOCUMENT_PROCESSING,
                            message="Extracted DOCX text exceeds configured max_decompressed_bytes.",
                        ),
                    ),
                )
            if full_parts:
                offset += 1
            char_start = offset
            char_end = offset + len(row_text)
            segments.append(
                DocumentSegment(
                    text=row_text,
                    char_start=char_start,
                    char_end=char_end,
                    paragraph=paragraph_index,
                    heading=current_heading,
                )
            )
            full_parts.append(row_text)
            offset = char_end

    full_text = "\n".join(full_parts)
    if not full_text.strip():
        return ParseResult(
            document=None,
            errors=(
                DiagnosticIssue(
                    code="no_extractable_text",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.DOCUMENT_PROCESSING,
                    message="DOCX document contains no extractable text.",
                ),
            ),
        )

    return ParseResult(
        document=PreparedDocument(
            source=source,
            format=DocumentFormat.DOCX,
            full_text=full_text,
            segments=tuple(segments),
            page_count=None,
        )
    )

"""Safe document input loader enforcing path checks, magic-byte inspection, and limits."""

from __future__ import annotations

import io
import os
import zipfile
from dataclasses import dataclass, field
from pathlib import Path
from uuid import uuid4

from structa_maestro.config import DocumentLimits
from structa_maestro.contracts.enums import DocumentFormat, IssueSeverity, PipelineStage
from structa_maestro.contracts.models import DiagnosticIssue, SourceMetadata
from structa_maestro.documents.docx_parser import parse_docx_bytes
from structa_maestro.documents.models import PreparedDocument
from structa_maestro.documents.pdf_parser import parse_pdf_bytes
from structa_maestro.documents.txt_parser import parse_txt_bytes

_MEDIA_TYPES: dict[DocumentFormat, str] = {
    DocumentFormat.TXT: "text/plain",
    DocumentFormat.PDF: "application/pdf",
    DocumentFormat.DOCX: (
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
    ),
}

_SUPPORTED_EXTENSIONS: frozenset[str] = frozenset({".txt", ".pdf", ".docx"})


@dataclass(frozen=True, slots=True)
class DocumentLoadResult:
    """Result of document loading and text preparation."""

    source: SourceMetadata
    document: PreparedDocument | None = None
    errors: list[DiagnosticIssue] = field(default_factory=list)
    warnings: list[DiagnosticIssue] = field(default_factory=list)


def _detect_format(raw: bytes, extension: str) -> tuple[DocumentFormat | None, str | None]:
    """Detect actual document format from magic bytes rather than blindly trusting extensions."""
    if raw.startswith(b"%PDF-"):
        return DocumentFormat.PDF, None

    if raw.startswith((b"PK\x03\x04", b"PK\x05\x06", b"PK\x07\x08")):
        try:
            with zipfile.ZipFile(io.BytesIO(raw), "r") as zf:
                if "word/document.xml" in zf.namelist():
                    return DocumentFormat.DOCX, None
                return None, "ZIP archive does not contain a DOCX document (word/document.xml)."
        except zipfile.BadZipFile:
            if extension == ".docx":
                return DocumentFormat.DOCX, None
            return None, "Corrupted archive or unsupported binary container."

    if extension == ".pdf":
        return None, "File has .pdf extension but does not start with a valid %PDF header."
    if extension == ".docx":
        return None, "File has .docx extension but is not a valid DOCX archive."
    if extension == ".txt":
        return DocumentFormat.TXT, None

    if extension and extension not in _SUPPORTED_EXTENSIONS:
        return None, f"Unsupported document format extension: {extension!r}."

    # Extensionless file: attempt plain text only if not binary
    return DocumentFormat.TXT, None


def load_document(
    path: str | Path,
    *,
    limits: DocumentLimits | None = None,
    document_id: str | None = None,
) -> DocumentLoadResult:
    """Inspect, validate, and parse a single TXT, text-based PDF, or DOCX document safely."""
    active_limits = limits or DocumentLimits()
    doc_path = Path(path)
    doc_id = document_id.strip() if document_id and document_id.strip() else str(uuid4())
    # Basename only to avoid leaking local host paths in canonical metadata
    safe_filename = doc_path.name if doc_path.name else None
    base_source = SourceMetadata(document_id=doc_id, filename=safe_filename, media_type=None)

    if "\x00" in str(path):
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="invalid_input",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Document path contains invalid null byte.",
                )
            ],
        )

    try:
        exists = doc_path.exists()
    except OSError:
        exists = False

    if not exists:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="file_not_found",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Input document path does not exist.",
                )
            ],
        )

    if doc_path.is_dir():
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="invalid_input",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Input path refers to a directory rather than a regular file.",
                )
            ],
        )

    if not doc_path.is_file():
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="invalid_input",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Input path is not a regular readable file.",
                )
            ],
        )

    if not os.access(doc_path, os.R_OK):
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="permission_denied",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Input document cannot be read due to file permissions.",
                )
            ],
        )

    try:
        file_size = doc_path.stat().st_size
    except OSError:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="invalid_input",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Unable to inspect input document file metadata.",
                )
            ],
        )

    if file_size == 0:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="empty_document",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Input document is empty (zero bytes).",
                )
            ],
        )

    if file_size > active_limits.max_file_bytes:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="resource_limit_exceeded",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message=(
                        f"Input document size ({file_size} bytes) exceeds configured "
                        f"max_file_bytes limit ({active_limits.max_file_bytes} bytes)."
                    ),
                )
            ],
        )

    try:
        raw = doc_path.read_bytes()
    except PermissionError:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="permission_denied",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Permission denied while reading input document.",
                )
            ],
        )
    except OSError:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="invalid_input",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Failed to read input document bytes.",
                )
            ],
        )

    if len(raw) > active_limits.max_file_bytes:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="resource_limit_exceeded",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Input document grew beyond configured max_file_bytes while reading.",
                )
            ],
        )

    ext = doc_path.suffix.lower()
    detected_format, detect_err = _detect_format(raw, ext)
    if detected_format is None:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="unsupported_format",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message=detect_err or "Unsupported document format.",
                )
            ],
        )

    warnings: list[DiagnosticIssue] = []
    if ext and ext in _SUPPORTED_EXTENSIONS and ext != f".{detected_format.value}":
        warnings.append(
            DiagnosticIssue(
                code="extension_mismatch",
                severity=IssueSeverity.WARNING,
                stage=PipelineStage.INPUT,
                message=(
                    f"File extension {ext!r} does not match detected content format "
                    f"{detected_format.value!r}; processed using detected format."
                ),
            )
        )

    source = SourceMetadata(
        document_id=doc_id,
        filename=safe_filename,
        media_type=_MEDIA_TYPES[detected_format],
    )

    if detected_format == DocumentFormat.TXT:
        parsed = parse_txt_bytes(raw, source, active_limits)
    elif detected_format == DocumentFormat.PDF:
        parsed = parse_pdf_bytes(raw, source, active_limits)
    else:
        parsed = parse_docx_bytes(raw, source, active_limits)

    return DocumentLoadResult(
        source=source,
        document=parsed.document,
        errors=list(parsed.errors),
        warnings=warnings + list(parsed.warnings),
    )

"""Dedicated non-coercing deterministic schema validator (FR-024..FR-026, Clarification Q4)."""

from __future__ import annotations

import re
from collections.abc import Mapping
from dataclasses import dataclass
from datetime import date, datetime
from decimal import Decimal
from typing import Any

from structa_maestro.contracts.enums import (
    ExtractionCardinality,
    FieldPresence,
    FieldType,
    IssueSeverity,
    PipelineStage,
    ValidationStatus,
)
from structa_maestro.contracts.models import DiagnosticIssue, ValidationOutcome
from structa_maestro.schema.models import ExtractionSchema, FieldSpec


@dataclass(frozen=True, slots=True)
class RecordValidationResult:
    """Deterministic validation outcomes for one record and each of its fields."""

    record_outcome: ValidationOutcome
    field_outcomes: dict[str, ValidationOutcome]


def _make_error(
    *,
    code: str,
    message: str,
    record_id: str | None,
    field_path: str | None,
    expected: str | None = None,
    actual: str | None = None,
) -> DiagnosticIssue:
    return DiagnosticIssue(
        code=code,
        severity=IssueSeverity.ERROR,
        stage=PipelineStage.VALIDATION,
        message=message,
        record_id=record_id,
        field_path=field_path,
        expected=expected,
        actual=actual,
    )


def _safe_type_name(value: Any) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, Decimal):
        return "decimal"
    if isinstance(value, float):
        return "float"
    if isinstance(value, datetime):
        return "datetime"
    if isinstance(value, date):
        return "date"
    if isinstance(value, str):
        return "string"
    if isinstance(value, list):
        return "array"
    if isinstance(value, dict):
        return "object"
    return type(value).__name__


class DeterministicValidator:
    """Evaluates extracted records strictly against ExtractionSchema with zero value coercion."""

    def validate_record(
        self,
        fields: Mapping[str, tuple[FieldPresence, Any]],
        schema: ExtractionSchema,
        *,
        record_id: str,
    ) -> RecordValidationResult:
        """Deterministically validate one record's fields against schema."""
        field_outcomes: dict[str, ValidationOutcome] = {}
        all_errors: list[DiagnosticIssue] = []

        # 1. Validate every declared schema field in deterministic order
        for field_name, spec in schema.fields.items():
            presence, value = fields.get(field_name, (FieldPresence.MISSING, None))
            errs = self._validate_value(
                spec=spec,
                presence=presence,
                value=value,
                record_id=record_id,
                field_path=field_name,
            )
            outcome = ValidationOutcome(
                status=ValidationStatus.INVALID if errs else ValidationStatus.VALID,
                errors=errs,
            )
            field_outcomes[field_name] = outcome
            all_errors.extend(errs)

        # 2. Check unexpected extra fields (rejected by default per Clarification Q4)
        for extra_name in sorted(set(fields.keys()) - set(schema.fields.keys())):
            presence, _ = fields[extra_name]
            if presence == FieldPresence.MISSING:
                field_outcomes[extra_name] = ValidationOutcome(status=ValidationStatus.VALID)
                continue
            if not schema.allow_additional_fields:
                err = _make_error(
                    code="unexpected_field",
                    message=f"Unexpected field '{extra_name}' is not declared in schema.",
                    record_id=record_id,
                    field_path=extra_name,
                    expected="declared schema field only",
                    actual=extra_name,
                )
                field_outcomes[extra_name] = ValidationOutcome(
                    status=ValidationStatus.INVALID,
                    errors=[err],
                )
                all_errors.append(err)
            else:
                field_outcomes[extra_name] = ValidationOutcome(status=ValidationStatus.VALID)

        record_outcome = ValidationOutcome(
            status=ValidationStatus.INVALID if all_errors else ValidationStatus.VALID,
            errors=all_errors,
        )
        return RecordValidationResult(
            record_outcome=record_outcome,
            field_outcomes=field_outcomes,
        )

    def validate_result_cardinality(
        self,
        record_outcomes: list[ValidationOutcome],
        schema: ExtractionSchema,
        *,
        has_records: bool,
        failed_before_validation: bool,
    ) -> ValidationOutcome:
        """Aggregate record-level validation outcomes and check schema cardinality rules."""
        if failed_before_validation and not has_records:
            return ValidationOutcome(status=ValidationStatus.NOT_VALIDATED)

        top_errors: list[DiagnosticIssue] = []
        if schema.cardinality == ExtractionCardinality.SINGLE:
            if len(record_outcomes) == 0:
                top_errors.append(
                    _make_error(
                        code="missing_record",
                        message="Single-record schema expected 1 record, but 0 records were extracted.",
                        record_id=None,
                        field_path=None,
                        expected="1 record",
                        actual="0 records",
                    )
                )
            elif len(record_outcomes) > 1:
                top_errors.append(
                    _make_error(
                        code="cardinality_violation",
                        message=(
                            f"Single-record schema expected 1 record, "
                            f"but {len(record_outcomes)} records were extracted."
                        ),
                        record_id=None,
                        field_path=None,
                        expected="1 record",
                        actual=f"{len(record_outcomes)} records",
                    )
                )

        for rec_outcome in record_outcomes:
            top_errors.extend(rec_outcome.errors)

        return ValidationOutcome(
            status=ValidationStatus.INVALID if top_errors else ValidationStatus.VALID,
            errors=top_errors,
        )

    def _validate_value(
        self,
        *,
        spec: FieldSpec,
        presence: FieldPresence,
        value: Any,
        record_id: str,
        field_path: str,
    ) -> list[DiagnosticIssue]:
        if presence == FieldPresence.MISSING:
            if spec.required:
                return [
                    _make_error(
                        code="missing_required",
                        message=f"Required field '{field_path}' is missing.",
                        record_id=record_id,
                        field_path=field_path,
                        expected=f"required {spec.field_type.value}",
                        actual="missing",
                    )
                ]
            return []

        if value is None:
            if spec.nullable:
                return []
            return [
                _make_error(
                    code="disallowed_null",
                    message=f"Field '{field_path}' does not allow null values.",
                    record_id=record_id,
                    field_path=field_path,
                    expected=f"non-null {spec.field_type.value}",
                    actual="null",
                )
            ]

        errors: list[DiagnosticIssue] = []
        ft = spec.field_type
        c = spec.constraints

        # Strict type checks (NO silent coercion!)
        if ft == FieldType.STRING:
            if not isinstance(value, str):
                return [
                    _make_error(
                        code="type_mismatch",
                        message=f"Field '{field_path}' expected string, got {_safe_type_name(value)}.",
                        record_id=record_id,
                        field_path=field_path,
                        expected="string",
                        actual=_safe_type_name(value),
                    )
                ]
            if c.min_length is not None and len(value) < c.min_length:
                errors.append(
                    _make_error(
                        code="constraint_violation",
                        message=f"Field '{field_path}' length is below min_length ({c.min_length}).",
                        record_id=record_id,
                        field_path=field_path,
                        expected=f"length >= {c.min_length}",
                        actual=f"length {len(value)}",
                    )
                )
            if c.max_length is not None and len(value) > c.max_length:
                errors.append(
                    _make_error(
                        code="constraint_violation",
                        message=f"Field '{field_path}' length exceeds max_length ({c.max_length}).",
                        record_id=record_id,
                        field_path=field_path,
                        expected=f"length <= {c.max_length}",
                        actual=f"length {len(value)}",
                    )
                )
            if c.pattern is not None and re.search(c.pattern, value) is None:
                errors.append(
                    _make_error(
                        code="constraint_violation",
                        message=f"Field '{field_path}' does not match required pattern.",
                        record_id=record_id,
                        field_path=field_path,
                        expected=f"pattern {c.pattern}",
                        actual="pattern mismatch",
                    )
                )

        elif ft == FieldType.INTEGER:
            if isinstance(value, bool) or not isinstance(value, int):
                return [
                    _make_error(
                        code="type_mismatch",
                        message=(
                            f"Field '{field_path}' expected integer, got {_safe_type_name(value)}."
                        ),
                        record_id=record_id,
                        field_path=field_path,
                        expected="integer",
                        actual=_safe_type_name(value),
                    )
                ]
            if c.min_value is not None and value < c.min_value:
                errors.append(
                    _make_error(
                        code="constraint_violation",
                        message=f"Field '{field_path}' is below min_value ({c.min_value}).",
                        record_id=record_id,
                        field_path=field_path,
                        expected=f">= {c.min_value}",
                        actual="below minimum",
                    )
                )
            if c.max_value is not None and value > c.max_value:
                errors.append(
                    _make_error(
                        code="constraint_violation",
                        message=f"Field '{field_path}' exceeds max_value ({c.max_value}).",
                        record_id=record_id,
                        field_path=field_path,
                        expected=f"<= {c.max_value}",
                        actual="above maximum",
                    )
                )

        elif ft == FieldType.DECIMAL:
            if isinstance(value, bool) or not isinstance(value, (Decimal, int, float)):
                return [
                    _make_error(
                        code="type_mismatch",
                        message=(
                            f"Field '{field_path}' expected decimal, got {_safe_type_name(value)}."
                        ),
                        record_id=record_id,
                        field_path=field_path,
                        expected="decimal",
                        actual=_safe_type_name(value),
                    )
                ]
            dec_val = value if isinstance(value, Decimal) else Decimal(str(value))
            if dec_val.is_nan() or dec_val.is_infinite():
                return [
                    _make_error(
                        code="type_mismatch",
                        message=f"Field '{field_path}' must be a finite decimal value.",
                        record_id=record_id,
                        field_path=field_path,
                        expected="finite decimal",
                        actual="non-finite",
                    )
                ]
            if c.min_value is not None and dec_val < Decimal(str(c.min_value)):
                errors.append(
                    _make_error(
                        code="constraint_violation",
                        message=f"Field '{field_path}' is below min_value ({c.min_value}).",
                        record_id=record_id,
                        field_path=field_path,
                        expected=f">= {c.min_value}",
                        actual="below minimum",
                    )
                )
            if c.max_value is not None and dec_val > Decimal(str(c.max_value)):
                errors.append(
                    _make_error(
                        code="constraint_violation",
                        message=f"Field '{field_path}' exceeds max_value ({c.max_value}).",
                        record_id=record_id,
                        field_path=field_path,
                        expected=f"<= {c.max_value}",
                        actual="above maximum",
                    )
                )

        elif ft == FieldType.BOOLEAN:
            if not isinstance(value, bool):
                return [
                    _make_error(
                        code="type_mismatch",
                        message=(
                            f"Field '{field_path}' expected boolean, got {_safe_type_name(value)}."
                        ),
                        record_id=record_id,
                        field_path=field_path,
                        expected="boolean",
                        actual=_safe_type_name(value),
                    )
                ]

        elif ft == FieldType.DATE:
            if isinstance(value, datetime) or not isinstance(value, date):
                return [
                    _make_error(
                        code="type_mismatch",
                        message=f"Field '{field_path}' expected date, got {_safe_type_name(value)}.",
                        record_id=record_id,
                        field_path=field_path,
                        expected="date",
                        actual=_safe_type_name(value),
                    )
                ]

        elif ft == FieldType.ARRAY:
            if not isinstance(value, list):
                return [
                    _make_error(
                        code="type_mismatch",
                        message=f"Field '{field_path}' expected array, got {_safe_type_name(value)}.",
                        record_id=record_id,
                        field_path=field_path,
                        expected="array",
                        actual=_safe_type_name(value),
                    )
                ]
            if c.min_items is not None and len(value) < c.min_items:
                errors.append(
                    _make_error(
                        code="constraint_violation",
                        message=f"Field '{field_path}' has fewer than min_items ({c.min_items}).",
                        record_id=record_id,
                        field_path=field_path,
                        expected=f"items >= {c.min_items}",
                        actual=f"{len(value)} items",
                    )
                )
            if c.max_items is not None and len(value) > c.max_items:
                errors.append(
                    _make_error(
                        code="constraint_violation",
                        message=f"Field '{field_path}' exceeds max_items ({c.max_items}).",
                        record_id=record_id,
                        field_path=field_path,
                        expected=f"items <= {c.max_items}",
                        actual=f"{len(value)} items",
                    )
                )
            if spec.items is not None:
                for idx, elem in enumerate(value):
                    errors.extend(
                        self._validate_value(
                            spec=spec.items,
                            presence=FieldPresence.PRESENT,
                            value=elem,
                            record_id=record_id,
                            field_path=f"{field_path}[{idx}]",
                        )
                    )

        elif ft == FieldType.OBJECT:
            if not isinstance(value, dict):
                return [
                    _make_error(
                        code="type_mismatch",
                        message=(
                            f"Field '{field_path}' expected object, got {_safe_type_name(value)}."
                        ),
                        record_id=record_id,
                        field_path=field_path,
                        expected="object",
                        actual=_safe_type_name(value),
                    )
                ]
            props = spec.properties or {}
            for prop_name, prop_spec in props.items():
                if prop_name in value:
                    p_presence = FieldPresence.PRESENT
                    p_val = value[prop_name]
                else:
                    p_presence = FieldPresence.MISSING
                    p_val = None
                errors.extend(
                    self._validate_value(
                        spec=prop_spec,
                        presence=p_presence,
                        value=p_val,
                        record_id=record_id,
                        field_path=f"{field_path}.{prop_name}",
                    )
                )
            if not spec.allow_additional_fields:
                for extra_key in sorted(set(value.keys()) - set(props.keys())):
                    errors.append(
                        _make_error(
                            code="unexpected_field",
                            message=(
                                f"Unexpected nested field '{field_path}.{extra_key}' "
                                "is not declared in schema."
                            ),
                            record_id=record_id,
                            field_path=f"{field_path}.{extra_key}",
                            expected="declared nested property only",
                            actual=str(extra_key),
                        )
                    )

        # Allowed values (enum) check
        if c.allowed_values is not None and not _value_in_allowed(value, c.allowed_values):
            errors.append(
                _make_error(
                    code="constraint_violation",
                    message=f"Field '{field_path}' value is not in allowed_values.",
                    record_id=record_id,
                    field_path=field_path,
                    expected=f"one of {list(c.allowed_values)}",
                    actual="disallowed value",
                )
            )

        return errors


def _value_in_allowed(value: Any, allowed: tuple[Any, ...]) -> bool:
    for candidate in allowed:
        if isinstance(value, bool) != isinstance(candidate, bool):
            continue
        if value == candidate:
            return True
    return False

"""Provenance association, source location mapping, and evidence integrity verification."""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import date
from decimal import Decimal
from typing import Any

from structa_maestro.contracts.enums import (
    EvidenceRelationship,
    FieldPresence,
    IssueSeverity,
    PipelineStage,
)
from structa_maestro.contracts.models import (
    DiagnosticIssue,
    ProvenanceEvidence,
    SourceLocation,
)
from structa_maestro.documents.models import DocumentSegment, PreparedDocument
from structa_maestro.strategies.base import ProposedEvidence

_MAX_EXCERPT_CHARS = 500
_WHITESPACE_RE = re.compile(r"\s+")


@dataclass(frozen=True, slots=True)
class ProvenanceAssociationResult:
    """Verified provenance entries and provenance-stage warnings for one extracted field."""

    evidence: list[ProvenanceEvidence] = field(default_factory=list)
    warnings: list[DiagnosticIssue] = field(default_factory=list)


def _collapse_ws(text: str) -> str:
    return _WHITESPACE_RE.sub(" ", text).strip()


def _find_span(full_text: str, quote: str) -> tuple[int, int] | None:
    if not quote or not quote.strip():
        return None
    idx = full_text.find(quote)
    if idx != -1:
        return idx, idx + len(quote)

    # Fallback: whitespace-tolerant search preserving original offsets
    tokens = _collapse_ws(quote).split(" ")
    if not tokens:
        return None
    pattern = r"\s+".join(re.escape(tok) for tok in tokens)
    match = re.search(pattern, full_text)
    if match is not None:
        return match.start(), match.end()
    return None


def _location_from_span(
    segments: tuple[DocumentSegment, ...],
    char_start: int,
    char_end: int,
) -> SourceLocation:
    overlapping = [
        seg for seg in segments if seg.char_end >= char_start and seg.char_start <= char_end
    ]
    if not overlapping:
        return SourceLocation(char_start=char_start, char_end=char_end)

    first = overlapping[0]
    last = overlapping[-1]
    line_start = first.line_start
    line_end = last.line_end if last.line_end is not None else first.line_end
    if line_start is not None and line_end is not None and line_end < line_start:
        line_end = line_start

    return SourceLocation(
        page=first.page,
        paragraph=first.paragraph,
        line_start=line_start,
        line_end=line_end,
        char_start=char_start,
        char_end=char_end,
        section=first.heading,
    )


def _scalar_value_supported_by_excerpt(value: Any, excerpt: str) -> bool:
    """Verify whether a direct supporting excerpt plausibly supports a scalar extracted value."""
    if value is None or isinstance(value, (bool, dict, list)):
        return True
    norm_excerpt = _collapse_ws(excerpt).lower()
    if isinstance(value, str):
        val = _collapse_ws(value).lower()
        if not val:
            return True
        return val in norm_excerpt
    if isinstance(value, Decimal):
        candidates = {str(value), format(value.normalize(), "f")}
        stripped_excerpt = norm_excerpt.replace(",", "")
        return any(c.lower() in stripped_excerpt for c in candidates)
    if isinstance(value, int):
        stripped_excerpt = norm_excerpt.replace(",", "")
        return str(value) in stripped_excerpt
    if isinstance(value, date):
        return value.isoformat() in norm_excerpt or str(value.year) in norm_excerpt
    return True


def _parse_relationship(raw: str) -> EvidenceRelationship:
    try:
        return EvidenceRelationship(raw.lower())
    except ValueError:
        return EvidenceRelationship.DIRECT


class ProvenanceAssociator:
    """Verifies candidate source quotes against PreparedDocument without fabricating locations."""

    def __init__(self, *, max_excerpt_chars: int = _MAX_EXCERPT_CHARS) -> None:
        self._max_excerpt_chars = max_excerpt_chars

    def associate(
        self,
        *,
        document: PreparedDocument,
        proposed_evidence: tuple[ProposedEvidence, ...],
        field_name: str,
        presence: FieldPresence,
        value: Any,
        record_id: str,
    ) -> ProvenanceAssociationResult:
        """Associate and verify zero, one, or multiple evidence passages for one field."""
        if not proposed_evidence:
            return ProvenanceAssociationResult()

        doc_id = document.source.document_id
        verified: list[ProvenanceEvidence] = []
        warnings: list[DiagnosticIssue] = []

        for item in proposed_evidence:
            # PRO-010: Reject evidence explicitly attributed to a foreign document
            if item.source_document_id is not None and item.source_document_id != doc_id:
                warnings.append(
                    DiagnosticIssue(
                        code="cross_document_evidence_rejected",
                        severity=IssueSeverity.WARNING,
                        stage=PipelineStage.PROVENANCE,
                        message=(
                            f"Rejected provenance referencing foreign document for field "
                            f"'{field_name}'."
                        ),
                        record_id=record_id,
                        field_path=field_name,
                    )
                )
                continue

            quote = item.quote.strip()
            if not quote:
                continue

            requested_rel = _parse_relationship(item.relationship)
            span = _find_span(document.full_text, quote)

            if span is None:
                # Quote does not appear in source document — never fabricate a location!
                excerpt, truncated = self._bound_excerpt(quote)
                verified.append(
                    ProvenanceEvidence(
                        source_document_id=doc_id,
                        location=None,
                        evidence=excerpt,
                        relationship=EvidenceRelationship.UNVERIFIED,
                        truncated=truncated,
                    )
                )
                warnings.append(
                    DiagnosticIssue(
                        code="unverified_evidence",
                        severity=IssueSeverity.WARNING,
                        stage=PipelineStage.PROVENANCE,
                        message=(
                            f"Proposed evidence for field '{field_name}' could not be located "
                            "in the source document."
                        ),
                        record_id=record_id,
                        field_path=field_name,
                    )
                )
                continue

            char_start, char_end = span
            original_excerpt = document.full_text[char_start:char_end]
            excerpt, truncated = self._bound_excerpt(original_excerpt)
            location = _location_from_span(document.segments, char_start, char_end)

            relationship = requested_rel
            if (
                presence == FieldPresence.PRESENT
                and requested_rel == EvidenceRelationship.DIRECT
                and not _scalar_value_supported_by_excerpt(value, original_excerpt)
            ):
                relationship = EvidenceRelationship.CONFLICTING
                warnings.append(
                    DiagnosticIssue(
                        code="evidence_value_conflict",
                        severity=IssueSeverity.WARNING,
                        stage=PipelineStage.PROVENANCE,
                        message=(
                            f"Cited direct evidence for field '{field_name}' does not match "
                            "the extracted value."
                        ),
                        record_id=record_id,
                        field_path=field_name,
                    )
                )

            verified.append(
                ProvenanceEvidence(
                    source_document_id=doc_id,
                    location=location,
                    evidence=excerpt,
                    relationship=relationship,
                    truncated=truncated,
                )
            )

        return ProvenanceAssociationResult(evidence=verified, warnings=warnings)

    def _bound_excerpt(self, text: str) -> tuple[str, bool]:
        if len(text) <= self._max_excerpt_chars:
            return text, False
        return text[: self._max_excerpt_chars], True

"""Confidence assessment normalization enforcing range bounds and uncalibrated MVP semantics."""

from __future__ import annotations

import math
from dataclasses import dataclass, field

from structa_maestro.contracts.enums import IssueSeverity, PipelineStage
from structa_maestro.contracts.models import ConfidenceAssessment, DiagnosticIssue


@dataclass(frozen=True, slots=True)
class ConfidenceNormalizationResult:
    """Normalized ConfidenceAssessment plus any range/metadata warnings."""

    confidence: ConfidenceAssessment | None
    warnings: list[DiagnosticIssue] = field(default_factory=list)


class ConfidenceNormalizer:
    """Enforces ConfidenceAssessment bounds and guarantees calibrated=False in MVP."""

    def normalize(
        self,
        *,
        raw_value: float | None,
        scale: str = "0-1",
        method: str | None = None,
        record_id: str | None = None,
        field_path: str | None = None,
        default_method: str = "extraction-assessment",
    ) -> ConfidenceNormalizationResult:
        """Normalize raw confidence metadata honestly without claiming probability calibration."""
        clean_scale = scale.strip() if isinstance(scale, str) and scale.strip() else "0-1"
        clean_method = (
            method.strip()
            if isinstance(method, str) and method.strip()
            else (default_method or "unknown")
        )

        if raw_value is None:
            return ConfidenceNormalizationResult(confidence=None)

        if isinstance(raw_value, bool) or not isinstance(raw_value, (int, float)):
            return ConfidenceNormalizationResult(
                confidence=ConfidenceAssessment(
                    value=None,
                    scale=clean_scale,
                    method=clean_method,
                    calibrated=False,
                ),
                warnings=[
                    DiagnosticIssue(
                        code="invalid_confidence_value",
                        severity=IssueSeverity.WARNING,
                        stage=PipelineStage.EXTRACTION,
                        message=(
                            f"Non-numeric confidence hint for field '{field_path}' was ignored."
                        ),
                        record_id=record_id,
                        field_path=field_path,
                    )
                ],
            )

        numeric = float(raw_value)
        if math.isnan(numeric) or math.isinf(numeric):
            return ConfidenceNormalizationResult(
                confidence=ConfidenceAssessment(
                    value=None,
                    scale=clean_scale,
                    method=clean_method,
                    calibrated=False,
                ),
                warnings=[
                    DiagnosticIssue(
                        code="invalid_confidence_range",
                        severity=IssueSeverity.WARNING,
                        stage=PipelineStage.EXTRACTION,
                        message=f"Non-finite confidence score for field '{field_path}' discarded.",
                        record_id=record_id,
                        field_path=field_path,
                    )
                ],
            )

        if clean_scale == "0-1" and not (0.0 <= numeric <= 1.0):
            return ConfidenceNormalizationResult(
                confidence=ConfidenceAssessment(
                    value=None,
                    scale=clean_scale,
                    method=clean_method,
                    calibrated=False,
                ),
                warnings=[
                    DiagnosticIssue(
                        code="invalid_confidence_range",
                        severity=IssueSeverity.WARNING,
                        stage=PipelineStage.EXTRACTION,
                        message=(
                            f"Confidence value for field '{field_path}' fell outside declared "
                            "scale '0-1' and was marked unavailable."
                        ),
                        record_id=record_id,
                        field_path=field_path,
                    )
                ],
            )

        return ConfidenceNormalizationResult(
            confidence=ConfidenceAssessment(
                value=round(numeric, 6),
                scale=clean_scale,
                method=clean_method,
                calibrated=False,
            )
        )

