"""Golden dataset manifest loader, pre-flight integrity validator, and subset filter."""

from __future__ import annotations

import json
from pathlib import Path

from evals.models import (
    ChallengeProfile,
    DocumentCategory,
    EvaluationFilter,
    GoldenCase,
    GoldenDatasetManifest,
)
from structa_maestro.contracts.enums import DocumentFormat
from structa_maestro.exceptions import SchemaDefinitionError
from structa_maestro.schema.models import ExtractionSchema

DEFAULT_MANIFEST_PATH = Path(__file__).parent / "dataset" / "manifest.json"
REQUIRED_FULL_CORPUS_SIZE = 50


def load_dataset(
    manifest_path: str | Path = DEFAULT_MANIFEST_PATH,
    *,
    validate_full_corpus: bool = True,
) -> GoldenDatasetManifest:
    """Load the versioned golden manifest (resolving split category files) and validate it."""
    root_path = Path(manifest_path)
    if not root_path.exists():
        raise ValueError(f"Golden dataset manifest not found: {root_path}")

    raw = json.loads(root_path.read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        raise ValueError("Golden dataset manifest root must be a JSON object.")

    cases_raw: list[object] = []
    if "category_files" in raw:
        cat_files = raw["category_files"]
        if not isinstance(cat_files, list) or not cat_files:
            raise ValueError("Manifest 'category_files' must be a non-empty list of paths.")
        for rel in cat_files:
            cat_path = root_path.parent / str(rel)
            if not cat_path.exists():
                raise ValueError(f"Missing category manifest file: {cat_path}")
            cat_data = json.loads(cat_path.read_text(encoding="utf-8"))
            if isinstance(cat_data, dict) and isinstance(cat_data.get("cases"), list):
                cases_raw.extend(cat_data["cases"])
            elif isinstance(cat_data, list):
                cases_raw.extend(cat_data)
            else:
                raise ValueError(f"Invalid category manifest structure in {cat_path.name}")
    elif isinstance(raw.get("cases"), list):
        cases_raw.extend(raw["cases"])
    else:
        raise ValueError("Manifest must declare either 'category_files' or 'cases'.")

    manifest = GoldenDatasetManifest.model_validate(
        {
            "dataset_version": raw.get("dataset_version"),
            "description": raw.get("description"),
            "cases": cases_raw,
        }
    )
    validate_dataset(manifest, require_full_corpus=validate_full_corpus)
    return manifest


def validate_dataset(
    manifest: GoldenDatasetManifest,
    *,
    require_full_corpus: bool = True,
) -> None:
    """Verify unique IDs, valid extraction schemas, and full-corpus coverage invariants."""
    seen_ids: set[str] = set()
    categories_present: set[DocumentCategory] = set()
    formats_present: set[DocumentFormat] = set()
    profiles_present: set[ChallengeProfile] = set()

    for case in manifest.cases:
        if case.case_id in seen_ids:
            raise ValueError(f"Duplicate golden case_id detected: {case.case_id!r}")
        seen_ids.add(case.case_id)

        try:
            ExtractionSchema.from_dict(case.schema_definition)
        except SchemaDefinitionError as exc:
            raise ValueError(
                f"Golden case {case.case_id!r} has an invalid schema_definition: {exc}"
            ) from exc

        categories_present.add(case.category)
        formats_present.add(case.format)
        profiles_present.update(case.challenge_profiles)

    if require_full_corpus:
        if len(manifest.cases) != REQUIRED_FULL_CORPUS_SIZE:
            raise ValueError(
                f"Full golden corpus requires exactly {REQUIRED_FULL_CORPUS_SIZE} cases, "
                f"found {len(manifest.cases)}."
            )
        missing_cats = set(DocumentCategory) - categories_present
        if missing_cats:
            raise ValueError(
                f"Golden corpus missing categories: {sorted(c.value for c in missing_cats)}"
            )
        missing_fmts = set(DocumentFormat) - formats_present
        if missing_fmts:
            raise ValueError(
                f"Golden corpus missing formats: {sorted(f.value for f in missing_fmts)}"
            )
        missing_profiles = set(ChallengeProfile) - profiles_present
        if missing_profiles:
            raise ValueError(
                f"Golden corpus missing challenge profiles: "
                f"{sorted(p.value for p in missing_profiles)}"
            )


def filter_cases(
    manifest: GoldenDatasetManifest,
    filters: EvaluationFilter | None = None,
) -> list[GoldenCase]:
    """Return golden cases matching filters; raise ValueError if selection is empty."""
    if filters is None or not filters.is_filtered:
        return list(manifest.cases)

    selected: list[GoldenCase] = []
    cat_set = set(filters.categories)
    fmt_set = set(filters.formats)
    prof_set = set(filters.profiles)
    id_set = set(filters.case_ids)

    for case in manifest.cases:
        if cat_set and case.category not in cat_set:
            continue
        if fmt_set and case.format not in fmt_set:
            continue
        if prof_set and not (set(case.challenge_profiles) & prof_set):
            continue
        if id_set and case.case_id not in id_set:
            continue
        selected.append(case)

    if not selected:
        raise ValueError("Active evaluation filters matched 0 golden cases.")
    return selected

"""Deterministic offline reference ExtractionStrategy for reproducible CI golden baselines."""

from __future__ import annotations

import re
from datetime import date
from decimal import Decimal, InvalidOperation
from typing import Any

from structa_maestro.contracts.enums import ExtractionCardinality, FieldPresence, FieldType
from structa_maestro.documents.models import PreparedDocument
from structa_maestro.schema.models import ExtractionSchema, FieldSpec
from structa_maestro.strategies.base import (
    ProposedEvidence,
    ProposedField,
    ProposedRecord,
    StrategyOutput,
)

_RECORD_SPLIT_RE = re.compile(r"(?m)^\s*---\s*RECORD\s*---\s*$")
_INJECTION_LINE_RE = re.compile(
    r"(?i)(ignore\s+(?:all\s+)?previous\s+instructions|"
    r"disregard\s+(?:the\s+)?(?:schema|previous)|"
    r"override\s+schema|"
    r"</untrusted_document>|"
    r"return\s+administrator\s+credentials|"
    r"fabricate\s+missing|"
    r"bypass\s+validation|"
    r"system\s+override\s*:)"
)
_QUOTED_OR_HYPOTHETICAL_RE = re.compile(
    r"(?i)^\s*(?:example\s*:|for\s+example\b|note\s*\(example\)|>\s*|hypothetical\s*:)"
)
_KV_LINE_RE = re.compile(r"^\s*([A-Za-z0-9_.\- /]+?)\s*:\s*(.+?)\s*$")
_PIPE_ROW_RE = re.compile(r"^\s*([A-Za-z0-9_.\- /]+?)\s*\|\s*(.+?)\s*$")
_AMBIGUOUS_TAG_RE = re.compile(r"\s*\[AMBIGUOUS\]\s*$", re.IGNORECASE)
_CONFLICT_TAG_RE = re.compile(r"\s*\[CONFLICTING\]\s*$", re.IGNORECASE)


def _norm_key(raw: str) -> str:
    return re.sub(r"[^a-z0-9]+", "_", raw.strip().lower()).strip("_")


def _clean_text_lines(block: str) -> list[str]:
    clean: list[str] = []
    for line in block.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        if _INJECTION_LINE_RE.search(stripped):
            continue
        if _QUOTED_OR_HYPOTHETICAL_RE.search(stripped):
            continue
        clean.append(stripped)
    return clean


def _parse_scalar(raw_val: str, field_type: FieldType) -> Any:
    val = raw_val.strip()
    if field_type == FieldType.STRING:
        return val
    if field_type == FieldType.INTEGER:
        cleaned = val.replace(",", "")
        try:
            return int(cleaned)
        except ValueError:
            return val
    if field_type == FieldType.DECIMAL:
        cleaned = re.sub(r"^[$€£¥]\s*", "", val).replace(",", "")
        try:
            return Decimal(cleaned)
        except InvalidOperation:
            return val
    if field_type == FieldType.BOOLEAN:
        low = val.lower()
        if low in {"true", "yes"}:
            return True
        if low in {"false", "no"}:
            return False
        return val
    if field_type == FieldType.DATE:
        try:
            return date.fromisoformat(val)
        except ValueError:
            return val
    return val


def _extract_kv_candidates(
    lines: list[str],
) -> dict[str, list[tuple[str, str, bool]]]:
    """Collect normalized_key -> list[(raw_value, original_line, flagged_ambiguous)]."""
    candidates: dict[str, list[tuple[str, str, bool]]] = {}
    for line in lines:
        m = _KV_LINE_RE.match(line)
        if m is None:
            m = _PIPE_ROW_RE.match(line)
        if m is None:
            continue
        raw_key, raw_val = m.group(1), m.group(2)
        # Skip table header rows like "Field | Value" or "Item | Amount"
        if _norm_key(raw_key) in {"field", "attribute", "column", "metric"} and _norm_key(
            raw_val
        ) in {"value", "amount", "details"}:
            continue
        ambiguous = False
        cleaned_val = raw_val
        if _AMBIGUOUS_TAG_RE.search(cleaned_val):
            ambiguous = True
            cleaned_val = _AMBIGUOUS_TAG_RE.sub("", cleaned_val).strip()
        if _CONFLICT_TAG_RE.search(cleaned_val):
            ambiguous = True
            cleaned_val = _CONFLICT_TAG_RE.sub("", cleaned_val).strip()

        key = _norm_key(raw_key)
        candidates.setdefault(key, []).append((cleaned_val, line, ambiguous))
    return candidates


def _extract_field_from_candidates(
    fname: str,
    spec: FieldSpec,
    candidates: dict[str, list[tuple[str, str, bool]]],
) -> ProposedField:
    if spec.field_type == FieldType.OBJECT and spec.properties:
        obj_val: dict[str, Any] = {}
        evidences: list[ProposedEvidence] = []
        any_ambig = False
        for prop_name, prop_spec in spec.properties.items():
            # Match either "parent.child" or "parent_child" or bare "child"
            hits = (
                candidates.get(_norm_key(f"{fname}.{prop_name}"))
                or candidates.get(_norm_key(f"{fname}_{prop_name}"))
                or candidates.get(_norm_key(prop_name))
            )
            if not hits:
                continue
            raw_v, quote, amb = hits[0]
            if len({h[0] for h in hits}) > 1:
                amb = True
            any_ambig = any_ambig or amb
            obj_val[prop_name] = _parse_scalar(raw_v, prop_spec.field_type)
            evidences.append(ProposedEvidence(quote=quote))
        if not obj_val:
            return ProposedField(presence=FieldPresence.MISSING, value=None)
        return ProposedField(
            presence=FieldPresence.PRESENT,
            value=obj_val,
            confidence=0.85 if any_ambig else 0.95,
            confidence_method="reference-deterministic",
            evidence=tuple(evidences),
            ambiguous=any_ambig,
        )

    hits = candidates.get(_norm_key(fname))
    if not hits:
        return ProposedField(presence=FieldPresence.MISSING, value=None)

    unique_vals = list(dict.fromkeys(h[0] for h in hits))
    ambiguous = any(h[2] for h in hits) or len(unique_vals) > 1
    evidences = [ProposedEvidence(quote=h[1]) for h in hits]

    if spec.field_type == FieldType.ARRAY and spec.items is not None:
        raw_joined = hits[0][0]
        parts = [p.strip() for p in raw_joined.split(",") if p.strip()]
        parsed_items = [_parse_scalar(p, spec.items.field_type) for p in parts]
        return ProposedField(
            presence=FieldPresence.PRESENT,
            value=parsed_items,
            confidence=0.90 if not ambiguous else 0.65,
            confidence_method="reference-deterministic",
            evidence=tuple(evidences),
            ambiguous=ambiguous,
        )

    raw_first = hits[0][0]
    if raw_first.lower() == "null" and spec.nullable:
        return ProposedField(
            presence=FieldPresence.PRESENT,
            value=None,
            confidence=0.95,
            confidence_method="reference-deterministic",
            evidence=tuple(evidences),
            ambiguous=ambiguous,
        )

    parsed_val = _parse_scalar(raw_first, spec.field_type)
    return ProposedField(
        presence=FieldPresence.PRESENT,
        value=parsed_val,
        confidence=0.55 if ambiguous else 0.95,
        confidence_method="reference-deterministic",
        evidence=tuple(evidences),
        ambiguous=ambiguous,
    )


class ReferenceDeterministicStrategy:
    """Offline deterministic ExtractionStrategy for reproducible 50-case golden CI baselines."""

    def __init__(self, *, name: str = "reference-deterministic") -> None:
        self._name = name

    @property
    def name(self) -> str:
        return self._name

    def extract_raw(
        self,
        document: PreparedDocument,
        schema: ExtractionSchema,
    ) -> StrategyOutput:
        text = document.full_text
        if schema.cardinality == ExtractionCardinality.MULTIPLE and _RECORD_SPLIT_RE.search(text):
            raw_blocks = [b for b in _RECORD_SPLIT_RE.split(text) if b.strip()]
        else:
            raw_blocks = [text]

        records: list[ProposedRecord] = []
        for block in raw_blocks:
            lines = _clean_text_lines(block)
            candidates = _extract_kv_candidates(lines)
            fields: dict[str, ProposedField] = {}
            any_present = False
            for fname, fspec in schema.fields.items():
                pf = _extract_field_from_candidates(fname, fspec, candidates)
                fields[fname] = pf
                if pf.presence == FieldPresence.PRESENT:
                    any_present = True
            if schema.cardinality == ExtractionCardinality.MULTIPLE and not any_present:
                continue
            records.append(ProposedRecord(fields=fields))

        return StrategyOutput(
            records=tuple(records),
            default_confidence_method="reference-deterministic",
        )

"""Multi-metric golden scoring, multi-record alignment, and repeated-trial aggregation."""

from __future__ import annotations

import re
from datetime import date
from decimal import Decimal, InvalidOperation
from typing import Any

from evals.models import (
    CaseOutcome,
    ExpectedFieldSpec,
    ExpectedRecordSpec,
    FieldScore,
    GoldenCase,
    MatchMode,
    MetricSummary,
    RecordOrderMode,
    TrialDistribution,
    TrialStat,
)
from structa_maestro.contracts.enums import (
    EvidenceRelationship,
    FieldPresence,
)
from structa_maestro.contracts.models import ExtractedField, ExtractedRecord, ExtractionResult

_WS_RE = re.compile(r"\s+")
_AMBIGUITY_WARNING_CODES = frozenset({"ambiguous_source_value", "evidence_value_conflict"})
_DISTRIBUTION_METRICS: tuple[str, ...] = (
    "field_exact_match_accuracy",
    "field_precision",
    "field_recall",
    "field_f1",
    "record_completeness",
    "record_level_accuracy",
    "hallucination_rate",
    "provenance_accuracy",
    "validation_pass_rate",
    "processing_failure_rate",
    "mean_latency_ms",
)


def _collapse_ws(text: str) -> str:
    return _WS_RE.sub(" ", text).strip()


def _compare_values(actual: Any, expected: Any, mode: MatchMode) -> bool:
    if isinstance(expected, dict) and isinstance(actual, dict):
        if set(expected.keys()) != set(actual.keys()):
            return False
        return all(_compare_values(actual[k], expected[k], mode) for k in expected)
    if isinstance(expected, list) and isinstance(actual, list):
        if len(expected) != len(actual):
            return False
        return all(
            _compare_values(a, e, mode) for a, e in zip(actual, expected, strict=True)
        )

    if mode == MatchMode.DECIMAL_EQUAL:
        try:
            return Decimal(str(actual)) == Decimal(str(expected))
        except InvalidOperation:
            return False

    if mode == MatchMode.DATE_ISO:
        a_str = actual.isoformat() if isinstance(actual, date) else str(actual)
        e_str = expected.isoformat() if isinstance(expected, date) else str(expected)
        return a_str == e_str

    if mode == MatchMode.CASEFOLD_WS:
        if isinstance(actual, str) and isinstance(expected, str):
            return _collapse_ws(actual).casefold() == _collapse_ws(expected).casefold()
        return bool(actual == expected)

    # Default: MatchMode.EXACT (strict equality; handles Decimal/date JSON string expectations)
    if isinstance(actual, Decimal) and isinstance(expected, str):
        try:
            return actual == Decimal(expected)
        except InvalidOperation:
            return False
    if isinstance(actual, date) and isinstance(expected, str):
        return actual.isoformat() == expected
    if isinstance(actual, bool) != isinstance(expected, bool):
        return False
    return bool(actual == expected)


def _verify_provenance(
    actual_field: ExtractedField,
    expected_evidence: list[str],
    expected_doc_id: str,
) -> bool:
    if not expected_evidence:
        return True
    for expected_snippet in expected_evidence:
        norm_expected = _collapse_ws(expected_snippet)
        found = any(
            ev.source_document_id == expected_doc_id
            and ev.relationship in {EvidenceRelationship.DIRECT, EvidenceRelationship.INFERRED}
            and norm_expected in _collapse_ws(ev.evidence)
            for ev in actual_field.provenance
        )
        if not found:
            return False
    return True


def _verify_ambiguity_handled(actual_field: ExtractedField | None) -> bool:
    if actual_field is None or actual_field.presence == FieldPresence.MISSING:
        return True
    if any(w.code in _AMBIGUITY_WARNING_CODES for w in actual_field.warnings):
        return True
    if any(ev.relationship == EvidenceRelationship.CONFLICTING for ev in actual_field.provenance):
        return True
    return False


def _record_overlap_score(
    actual: ExtractedRecord,
    expected: ExpectedRecordSpec,
    match_key_field: str | None,
) -> tuple[int, int]:
    key_hit = 0
    if match_key_field and match_key_field in expected.fields:
        exp_k = expected.fields[match_key_field]
        act_k = actual.fields.get(match_key_field)
        if (
            act_k is not None
            and act_k.presence == FieldPresence.PRESENT
            and exp_k.presence == FieldPresence.PRESENT
            and _compare_values(act_k.value, exp_k.value, exp_k.match_mode)
        ):
            key_hit = 1

    hits = 0
    for fname, exp_f in expected.fields.items():
        act_f = actual.fields.get(fname)
        if exp_f.presence == FieldPresence.MISSING:
            if act_f is None or act_f.presence == FieldPresence.MISSING:
                hits += 1
        elif act_f is not None and act_f.presence == FieldPresence.PRESENT:
            if _compare_values(act_f.value, exp_f.value, exp_f.match_mode):
                hits += 1
    return key_hit, hits


def _align_records(
    actual_records: list[ExtractedRecord],
    expected_records: list[ExpectedRecordSpec],
    order_mode: RecordOrderMode,
    match_key_field: str | None,
) -> list[tuple[ExpectedRecordSpec, ExtractedRecord | None]]:
    if order_mode == RecordOrderMode.ORDERED:
        return [
            (exp_rec, actual_records[idx] if idx < len(actual_records) else None)
            for idx, exp_rec in enumerate(expected_records)
        ]

    # Greedy optimal alignment by (match_key_hit, field_overlap_score)
    remaining_indices = set(range(len(actual_records)))
    aligned: list[tuple[ExpectedRecordSpec, ExtractedRecord | None]] = []
    for exp_rec in expected_records:
        best_idx: int | None = None
        best_score: tuple[int, int] = (-1, -1)
        for idx in sorted(remaining_indices):
            score = _record_overlap_score(actual_records[idx], exp_rec, match_key_field)
            if score > best_score:
                best_score = score
                best_idx = idx
        if best_idx is not None:
            remaining_indices.remove(best_idx)
            aligned.append((exp_rec, actual_records[best_idx]))
        else:
            aligned.append((exp_rec, None))
    return aligned


def score_case(
    *,
    case: GoldenCase,
    result: ExtractionResult | None,
    trial_index: int,
    latency_ms: float,
    runtime_error: str | None = None,
) -> CaseOutcome:
    """Score one canonical ExtractionResult against its GoldenCase expectations."""
    if result is None:
        return CaseOutcome(
            case_id=case.case_id,
            category=case.category,
            format=case.format,
            challenge_profiles=list(case.challenge_profiles),
            trial_index=trial_index,
            expected_status=case.expected_status,
            actual_status=case.expected_status
            if runtime_error is None
            else case.expected_status,
            status_matched=False,
            expected_validation=case.expected_validation,
            actual_validation=case.expected_validation,
            validation_matched=False,
            error_codes_matched=False,
            runtime_error=runtime_error or "missing_result",
            latency_ms=round(max(0.0, latency_ms), 3),
            field_scores=[],
            record_completeness=0.0,
            record_exact_accuracy=0.0,
            passed=False,
        )

    status_matched = result.status == case.expected_status
    validation_matched = result.validation.status == case.expected_validation

    actual_error_codes = {e.code for e in result.errors}
    for rec in result.records:
        actual_error_codes.update(e.code for e in rec.errors)
        actual_error_codes.update(e.code for e in rec.validation.errors)
    error_codes_matched = all(code in actual_error_codes for code in case.expected_error_codes)

    # Check adversarial forbidden extra fields were not silently accepted as valid
    adversarial_clean = True
    for forbidden in case.forbidden_extra_fields:
        for rec in result.records:
            ef = rec.fields.get(forbidden)
            if (
                ef is not None
                and ef.presence == FieldPresence.PRESENT
                and ef.validation.status.value == "valid"
            ):
                adversarial_clean = False

    aligned = _align_records(
        result.records,
        case.expected_records,
        case.record_order,
        case.match_key_field,
    )

    field_scores: list[FieldScore] = []
    rec_completeness_vals: list[float] = []
    exact_records = 0

    for exp_rec, act_rec in aligned:
        rec_expected_present = 0
        rec_correct_present = 0
        rec_all_ok = True

        if exp_rec.expected_validation is not None:
            if act_rec is None or act_rec.validation.status != exp_rec.expected_validation:
                rec_all_ok = False

        for fname, exp_field in exp_rec.fields.items():
            act_field = act_rec.fields.get(fname) if act_rec is not None else None
            actual_presence = (
                act_field.presence if act_field is not None else FieldPresence.MISSING
            )
            prov_expected = bool(exp_field.expected_evidence)
            ambig_expected = exp_field.expect_ambiguous
            ambig_handled = _verify_ambiguity_handled(act_field) if ambig_expected else True

            if exp_field.presence == FieldPresence.MISSING:
                hallucinated = actual_presence == FieldPresence.PRESENT
                matched = not hallucinated
                prov_verified = True
            else:
                rec_expected_present += 1
                hallucinated = False
                if act_field is None or actual_presence == FieldPresence.MISSING:
                    matched = False
                    prov_verified = not prov_expected
                else:
                    matched = _compare_values(act_field.value, exp_field.value, exp_field.match_mode)
                    if matched:
                        rec_correct_present += 1
                    prov_verified = (
                        _verify_provenance(act_field, exp_field.expected_evidence, case.case_id)
                        if prov_expected
                        else True
                    )

            if not matched or hallucinated or (prov_expected and not prov_verified) or (
                ambig_expected and not ambig_handled
            ):
                rec_all_ok = False

            field_scores.append(
                FieldScore(
                    field_name=fname,
                    expected_presence=exp_field.presence,
                    actual_presence=actual_presence,
                    matched=matched,
                    hallucinated=hallucinated,
                    provenance_expected=prov_expected,
                    provenance_verified=prov_verified,
                    ambiguity_expected=ambig_expected,
                    ambiguity_handled=ambig_handled,
                )
            )

        if rec_expected_present > 0:
            rec_completeness_vals.append(rec_correct_present / rec_expected_present)
        if rec_all_ok:
            exact_records += 1

    # Penalize extra unexpected records in multi-record cases
    record_count_ok = len(result.records) == len(case.expected_records)
    rec_comp = (
        sum(rec_completeness_vals) / len(rec_completeness_vals)
        if rec_completeness_vals
        else 1.0
    )
    rec_exact = (
        exact_records / len(case.expected_records)
        if case.expected_records
        else (1.0 if not result.records else 0.0)
    )

    all_fields_ok = all(
        fs.matched
        and not fs.hallucinated
        and (not fs.provenance_expected or fs.provenance_verified)
        and (not fs.ambiguity_expected or fs.ambiguity_handled)
        for fs in field_scores
    )
    passed = (
        runtime_error is None
        and status_matched
        and validation_matched
        and error_codes_matched
        and adversarial_clean
        and record_count_ok
        and all_fields_ok
    )

    return CaseOutcome(
        case_id=case.case_id,
        category=case.category,
        format=case.format,
        challenge_profiles=list(case.challenge_profiles),
        trial_index=trial_index,
        expected_status=case.expected_status,
        actual_status=result.status,
        status_matched=status_matched,
        expected_validation=case.expected_validation,
        actual_validation=result.validation.status,
        validation_matched=validation_matched,
        error_codes_matched=error_codes_matched,
        runtime_error=runtime_error,
        latency_ms=round(max(0.0, latency_ms), 3),
        field_scores=field_scores,
        record_completeness=round(rec_comp, 4),
        record_exact_accuracy=round(rec_exact, 4),
        passed=passed,
    )


def compute_metric_summary(outcomes: list[CaseOutcome]) -> MetricSummary:
    """Aggregate zero-denominator-safe metrics across a list of CaseOutcomes."""
    total_cases = len(outcomes)
    total_fields = 0
    expected_present = 0
    expected_missing = 0
    hallucination_count = 0
    expected_provenance = 0
    verified_provenance = 0
    exact_matches = 0
    tp = 0
    fp = 0
    fn = 0
    validation_matches = 0
    runtime_failures = 0

    for outcome in outcomes:
        if outcome.validation_matched:
            validation_matches += 1
        if outcome.runtime_error is not None:
            runtime_failures += 1
        for fs in outcome.field_scores:
            total_fields += 1
            if fs.expected_presence == FieldPresence.MISSING:
                expected_missing += 1
                if fs.hallucinated:
                    hallucination_count += 1
                    fp += 1
                else:
                    exact_matches += 1
            else:
                expected_present += 1
                if fs.provenance_expected:
                    expected_provenance += 1
                    if fs.provenance_verified:
                        verified_provenance += 1
                if fs.actual_presence == FieldPresence.MISSING:
                    fn += 1
                elif fs.matched:
                    tp += 1
                    exact_matches += 1
                else:
                    fp += 1
                    fn += 1

    precision = tp / (tp + fp) if (tp + fp) > 0 else 1.0
    recall = tp / (tp + fn) if (tp + fn) > 0 else 1.0
    f1 = (2.0 * precision * recall / (precision + recall)) if (precision + recall) > 0 else 0.0
    exact_acc = exact_matches / total_fields if total_fields > 0 else 1.0
    false_ext_rate = fp / (tp + fp) if (tp + fp) > 0 else 0.0
    missing_rate = fn / (tp + fn) if (tp + fn) > 0 else 0.0
    halluc_rate = hallucination_count / expected_missing if expected_missing > 0 else 0.0
    prov_acc = verified_provenance / expected_provenance if expected_provenance > 0 else 1.0
    val_rate = validation_matches / total_cases if total_cases > 0 else 1.0
    fail_rate = runtime_failures / total_cases if total_cases > 0 else 0.0
    rec_comp = (
        sum(o.record_completeness for o in outcomes) / total_cases if total_cases > 0 else 1.0
    )
    rec_acc = (
        sum(o.record_exact_accuracy for o in outcomes) / total_cases if total_cases > 0 else 1.0
    )
    mean_lat = sum(o.latency_ms for o in outcomes) / total_cases if total_cases > 0 else 0.0
    max_lat = max((o.latency_ms for o in outcomes), default=0.0)

    return MetricSummary(
        total_cases=total_cases,
        total_fields=total_fields,
        expected_present_fields=expected_present,
        expected_missing_fields=expected_missing,
        hallucination_count=hallucination_count,
        expected_provenance_fields=expected_provenance,
        field_exact_match_accuracy=round(exact_acc, 4),
        field_precision=round(precision, 4),
        field_recall=round(recall, 4),
        field_f1=round(f1, 4),
        record_completeness=round(rec_comp, 4),
        record_level_accuracy=round(rec_acc, 4),
        false_extraction_rate=round(false_ext_rate, 4),
        missing_field_rate=round(missing_rate, 4),
        hallucination_rate=round(halluc_rate, 4),
        provenance_accuracy=round(prov_acc, 4),
        validation_pass_rate=round(val_rate, 4),
        processing_failure_rate=round(fail_rate, 4),
        mean_latency_ms=round(mean_lat, 3),
        max_latency_ms=round(max_lat, 3),
    )


def compute_breakdowns(
    outcomes: list[CaseOutcome],
) -> tuple[dict[str, MetricSummary], dict[str, MetricSummary]]:
    """Compute per-category and per-challenge-profile MetricSummary maps."""
    by_cat_groups: dict[str, list[CaseOutcome]] = {}
    by_prof_groups: dict[str, list[CaseOutcome]] = {}
    for outcome in outcomes:
        by_cat_groups.setdefault(outcome.category.value, []).append(outcome)
        for prof in outcome.challenge_profiles:
            by_prof_groups.setdefault(prof.value, []).append(outcome)

    by_category = {
        cat: compute_metric_summary(items) for cat, items in sorted(by_cat_groups.items())
    }
    by_profile = {
        prof: compute_metric_summary(items) for prof, items in sorted(by_prof_groups.items())
    }
    return by_category, by_profile


def compute_trial_distribution(trial_summaries: list[MetricSummary]) -> TrialDistribution:
    """Compute mean, min, and max across trial summaries for every core metric (FR-014)."""
    dist: TrialDistribution = {}
    for metric_name in _DISTRIBUTION_METRICS:
        vals = [float(getattr(summary, metric_name)) for summary in trial_summaries]
        dist[metric_name] = TrialStat(
            mean=round(sum(vals) / len(vals), 4),
            min=round(min(vals), 4),
            max=round(max(vals), 4),
        )
    return dist

"""Baseline regression gating and side-by-side differential strategy comparison."""

from __future__ import annotations

from evals.models import (
    CaseDelta,
    CaseOutcome,
    ComparisonReport,
    DifferentialReport,
    EvaluationReport,
    RegressionThresholds,
)

_TRACKED_METRICS: tuple[str, ...] = (
    "field_exact_match_accuracy",
    "field_precision",
    "field_recall",
    "field_f1",
    "record_completeness",
    "record_level_accuracy",
    "false_extraction_rate",
    "missing_field_rate",
    "hallucination_rate",
    "provenance_accuracy",
    "validation_pass_rate",
    "processing_failure_rate",
)


def _index_first_trial_cases(report: EvaluationReport) -> dict[str, CaseOutcome]:
    indexed: dict[str, CaseOutcome] = {}
    for outcome in report.cases:
        if outcome.case_id not in indexed or outcome.trial_index == 1:
            indexed[outcome.case_id] = outcome
    return indexed


def _compute_deltas(candidate: EvaluationReport, baseline: EvaluationReport) -> dict[str, float]:
    deltas: dict[str, float] = {}
    for metric in _TRACKED_METRICS:
        cand_val = float(getattr(candidate.summary, metric))
        base_val = float(getattr(baseline.summary, metric))
        deltas[metric] = round(cand_val - base_val, 4)
    return deltas


def _describe_case_differences(
    base_case: CaseOutcome,
    cand_case: CaseOutcome,
) -> tuple[list[str], list[str]]:
    """Return (regression_details, improvement_details) comparing two outcomes for one case."""
    regressed: list[str] = []
    improved: list[str] = []

    if base_case.status_matched and not cand_case.status_matched:
        regressed.append(
            f"status regressed: {base_case.actual_status.value} -> {cand_case.actual_status.value}"
        )
    elif not base_case.status_matched and cand_case.status_matched:
        improved.append(f"status fixed: {cand_case.actual_status.value}")

    if base_case.validation_matched and not cand_case.validation_matched:
        regressed.append(
            f"validation regressed: {base_case.actual_validation.value} -> "
            f"{cand_case.actual_validation.value}"
        )
    elif not base_case.validation_matched and cand_case.validation_matched:
        improved.append(f"validation fixed: {cand_case.actual_validation.value}")

    base_fields = {f.field_name: f for f in base_case.field_scores}
    cand_fields = {f.field_name: f for f in cand_case.field_scores}
    for fname in sorted(set(base_fields) | set(cand_fields)):
        bf = base_fields.get(fname)
        cf = cand_fields.get(fname)
        if bf is None or cf is None:
            continue
        if not bf.hallucinated and cf.hallucinated:
            regressed.append(f"field '{fname}': newly hallucinated")
        elif bf.hallucinated and not cf.hallucinated:
            improved.append(f"field '{fname}': hallucination eliminated")

        if bf.matched and not cf.matched:
            regressed.append(f"field '{fname}': value mismatch")
        elif not bf.matched and cf.matched:
            improved.append(f"field '{fname}': value now matched")

        if bf.provenance_expected and bf.provenance_verified and not cf.provenance_verified:
            regressed.append(f"field '{fname}': provenance broken")
        elif bf.provenance_expected and not bf.provenance_verified and cf.provenance_verified:
            improved.append(f"field '{fname}': provenance fixed")

    return regressed, improved


def compare_against_baseline(
    candidate: EvaluationReport,
    baseline: EvaluationReport,
    thresholds: RegressionThresholds | None = None,
) -> ComparisonReport:
    """Compare candidate report against a stored baseline and enforce regression thresholds."""
    active_thresholds = thresholds or RegressionThresholds()
    version_match = candidate.dataset_version == baseline.dataset_version
    deltas = _compute_deltas(candidate, baseline)
    failure_reasons: list[str] = []

    if not version_match and not active_thresholds.allow_dataset_version_mismatch:
        failure_reasons.append(
            f"Dataset version mismatch: candidate={candidate.dataset_version!r} vs "
            f"baseline={baseline.dataset_version!r}."
        )

    # Strict anti-hallucination gate (FR-013): reject hallucination increases even if recall rises
    if deltas["hallucination_rate"] > active_thresholds.max_hallucination_increase:
        failure_reasons.append(
            f"Hallucination rate increased by +{deltas['hallucination_rate']:.4f} "
            f"(max allowed: +{active_thresholds.max_hallucination_increase:.4f})."
        )

    drop_checks = (
        ("field_exact_match_accuracy", active_thresholds.max_exact_match_drop, "Exact-match"),
        ("field_f1", active_thresholds.max_f1_drop, "Field F1"),
        ("provenance_accuracy", active_thresholds.max_provenance_drop, "Provenance accuracy"),
        ("validation_pass_rate", active_thresholds.max_validation_drop, "Validation pass rate"),
    )
    for metric_key, max_drop, label in drop_checks:
        drop = round(-deltas[metric_key], 4)
        if drop > max_drop:
            failure_reasons.append(
                f"{label} dropped by -{drop:.4f} (max allowed drop: {max_drop:.4f})."
            )

    if deltas["processing_failure_rate"] > active_thresholds.max_failure_rate_increase:
        failure_reasons.append(
            f"Processing failure rate increased by +{deltas['processing_failure_rate']:.4f} "
            f"(max allowed: +{active_thresholds.max_failure_rate_increase:.4f})."
        )

    base_cases = _index_first_trial_cases(baseline)
    cand_cases = _index_first_trial_cases(candidate)
    regressed_cases: list[CaseDelta] = []
    improved_cases: list[CaseDelta] = []

    for cid in sorted(set(base_cases) & set(cand_cases)):
        reg_details, imp_details = _describe_case_differences(base_cases[cid], cand_cases[cid])
        if reg_details:
            regressed_cases.append(
                CaseDelta(
                    case_id=cid,
                    category=cand_cases[cid].category.value,
                    direction="regressed",
                    details=reg_details,
                )
            )
        if imp_details:
            improved_cases.append(
                CaseDelta(
                    case_id=cid,
                    category=cand_cases[cid].category.value,
                    direction="improved",
                    details=imp_details,
                )
            )

    return ComparisonReport(
        baseline_dataset_version=baseline.dataset_version,
        candidate_dataset_version=candidate.dataset_version,
        dataset_version_match=version_match,
        baseline_strategy=baseline.strategy_name,
        candidate_strategy=candidate.strategy_name,
        thresholds=active_thresholds,
        metric_deltas=deltas,
        regressed_cases=regressed_cases,
        improved_cases=improved_cases,
        passed=len(failure_reasons) == 0,
        failure_reasons=failure_reasons,
    )


def diff_strategies(
    report_a: EvaluationReport,
    report_b: EvaluationReport,
) -> DifferentialReport:
    """Compare two evaluation reports side-by-side and list all case/field divergences (FR-015)."""
    version_match = report_a.dataset_version == report_b.dataset_version
    deltas = _compute_deltas(report_b, report_a)
    warnings: list[str] = []
    if not version_match:
        warnings.append(
            f"Dataset version mismatch: report A={report_a.dataset_version!r} vs "
            f"report B={report_b.dataset_version!r}; deltas may not be directly comparable."
        )

    cases_a = _index_first_trial_cases(report_a)
    cases_b = _index_first_trial_cases(report_b)
    divergent: list[CaseDelta] = []

    for cid in sorted(set(cases_a) | set(cases_b)):
        ca = cases_a.get(cid)
        cb = cases_b.get(cid)
        if ca is None and cb is not None:
            divergent.append(
                CaseDelta(
                    case_id=cid,
                    category=cb.category.value,
                    direction="diverged",
                    details=["present only in report B"],
                )
            )
            continue
        if cb is None and ca is not None:
            divergent.append(
                CaseDelta(
                    case_id=cid,
                    category=ca.category.value,
                    direction="diverged",
                    details=["present only in report A"],
                )
            )
            continue
        if ca is None or cb is None:
            continue

        details: list[str] = []
        if ca.actual_status != cb.actual_status:
            details.append(f"status: A={ca.actual_status.value} vs B={cb.actual_status.value}")
        if ca.actual_validation != cb.actual_validation:
            details.append(
                f"validation: A={ca.actual_validation.value} vs B={cb.actual_validation.value}"
            )

        fa = {f.field_name: f for f in ca.field_scores}
        fb = {f.field_name: f for f in cb.field_scores}
        for fname in sorted(set(fa) | set(fb)):
            left = fa.get(fname)
            right = fb.get(fname)
            if left is None or right is None:
                details.append(f"field '{fname}': evaluated in only one report")
                continue
            if (
                left.matched != right.matched
                or left.hallucinated != right.hallucinated
                or left.provenance_verified != right.provenance_verified
            ):
                details.append(
                    f"field '{fname}': A(matched={left.matched}, halluc={left.hallucinated}, "
                    f"prov={left.provenance_verified}) vs "
                    f"B(matched={right.matched}, halluc={right.hallucinated}, "
                    f"prov={right.provenance_verified})"
                )

        if details:
            divergent.append(
                CaseDelta(
                    case_id=cid,
                    category=ca.category.value,
                    direction="diverged",
                    details=details,
                )
            )

    return DifferentialReport(
        dataset_version_a=report_a.dataset_version,
        dataset_version_b=report_b.dataset_version,
        dataset_version_match=version_match,
        strategy_a=report_a.strategy_name,
        strategy_b=report_b.strategy_name,
        metric_deltas=deltas,
        divergent_cases=divergent,
        warnings=warnings,
    )

