"""Immutable configuration models and enums for OpenAICompatibleLLMStrategy."""

from __future__ import annotations

import math
from dataclasses import dataclass
from enum import Enum

from structa_maestro.exceptions import ConfigurationError

DEFAULT_MAX_INPUT_CHARS = 120_000


class StructuredOutputMode(str, Enum):
    """Structured output enforcement mode for OpenAI-compatible Chat Completions."""

    STRICT_WITH_FALLBACK = "strict_with_fallback"
    STRICT = "strict"
    JSON_OBJECT = "json_object"


class InputBudgetOverflowPolicy(str, Enum):
    """Action taken when prepared document text exceeds InputBudgetPolicy.max_input_chars."""

    REJECT = "reject"
    TRUNCATE = "truncate"


def parse_structured_output_mode(value: StructuredOutputMode | str) -> StructuredOutputMode:
    """Validate and normalize a StructuredOutputMode enum or string."""
    if isinstance(value, StructuredOutputMode):
        return value
    if isinstance(value, str):
        try:
            return StructuredOutputMode(value.strip().lower())
        except ValueError as exc:
            valid = ", ".join(m.value for m in StructuredOutputMode)
            raise ConfigurationError(
                f"Invalid structured_output_mode {value!r}; expected one of: {valid}."
            ) from exc
    raise ConfigurationError(
        "structured_output_mode must be a StructuredOutputMode or valid string."
    )


def parse_overflow_policy(value: InputBudgetOverflowPolicy | str) -> InputBudgetOverflowPolicy:
    """Validate and normalize an InputBudgetOverflowPolicy enum or string."""
    if isinstance(value, InputBudgetOverflowPolicy):
        return value
    if isinstance(value, str):
        try:
            return InputBudgetOverflowPolicy(value.strip().lower())
        except ValueError as exc:
            valid = ", ".join(p.value for p in InputBudgetOverflowPolicy)
            raise ConfigurationError(
                f"Invalid overflow_policy {value!r}; expected one of: {valid}."
            ) from exc
    raise ConfigurationError(
        "overflow_policy must be an InputBudgetOverflowPolicy or valid string."
    )


def parse_max_input_chars_arg(raw: str) -> int | None:
    """Parse CLI --max-input-chars argument accepting positive integer or case-insensitive 'none'."""
    cleaned = raw.strip()
    if cleaned.lower() == "none":
        return None
    try:
        parsed = int(cleaned)
    except ValueError as exc:
        raise ConfigurationError(
            f"Invalid --max-input-chars value {raw!r}; expected a positive integer or 'none'."
        ) from exc
    if parsed <= 0:
        raise ConfigurationError("InputBudgetPolicy.max_input_chars must be a positive integer.")
    return parsed


@dataclass(frozen=True, slots=True)
class RetryPolicy:
    """Bounded retry configuration for transient provider and output failures."""

    max_retries: int = 2
    initial_backoff_seconds: float = 0.5
    max_backoff_seconds: float = 8.0
    jitter: bool = True
    retry_on_malformed_output: bool = True
    max_total_seconds: float | None = None

    def __post_init__(self) -> None:
        if isinstance(self.max_retries, bool) or not isinstance(self.max_retries, int):
            raise ConfigurationError("RetryPolicy.max_retries must be an integer >= 0.")
        if self.max_retries < 0:
            raise ConfigurationError("RetryPolicy.max_retries must be an integer >= 0.")

        if (
            isinstance(self.initial_backoff_seconds, bool)
            or not isinstance(self.initial_backoff_seconds, (int, float))
            or not math.isfinite(self.initial_backoff_seconds)
            or self.initial_backoff_seconds < 0.0
        ):
            raise ConfigurationError(
                "RetryPolicy.initial_backoff_seconds must be a finite number >= 0.0."
            )
        object.__setattr__(self, "initial_backoff_seconds", float(self.initial_backoff_seconds))

        if (
            isinstance(self.max_backoff_seconds, bool)
            or not isinstance(self.max_backoff_seconds, (int, float))
            or not math.isfinite(self.max_backoff_seconds)
            or self.max_backoff_seconds < self.initial_backoff_seconds
        ):
            raise ConfigurationError(
                "RetryPolicy.max_backoff_seconds must be a finite number >= initial_backoff_seconds."
            )
        object.__setattr__(self, "max_backoff_seconds", float(self.max_backoff_seconds))

        if not isinstance(self.jitter, bool):
            raise ConfigurationError("RetryPolicy.jitter must be a boolean.")
        if not isinstance(self.retry_on_malformed_output, bool):
            raise ConfigurationError("RetryPolicy.retry_on_malformed_output must be a boolean.")

        if self.max_total_seconds is not None:
            if (
                isinstance(self.max_total_seconds, bool)
                or not isinstance(self.max_total_seconds, (int, float))
                or not math.isfinite(self.max_total_seconds)
                or self.max_total_seconds <= 0.0
            ):
                raise ConfigurationError(
                    "RetryPolicy.max_total_seconds must be a finite number > 0.0 or None."
                )
            object.__setattr__(self, "max_total_seconds", float(self.max_total_seconds))


@dataclass(frozen=True, slots=True)
class InputBudgetPolicy:
    """Configurable character-based input budget and overflow handling policy."""

    max_input_chars: int | None = DEFAULT_MAX_INPUT_CHARS
    overflow_policy: InputBudgetOverflowPolicy = InputBudgetOverflowPolicy.REJECT

    def __post_init__(self) -> None:
        if self.max_input_chars is not None and (
            isinstance(self.max_input_chars, bool)
            or not isinstance(self.max_input_chars, int)
            or self.max_input_chars <= 0
        ):
            raise ConfigurationError(
                "InputBudgetPolicy.max_input_chars must be a positive integer or None."
            )
        normalized = parse_overflow_policy(self.overflow_policy)
        object.__setattr__(self, "overflow_policy", normalized)

"""Pure deterministic helpers for LLM strategy hardening (zero external dependencies)."""

from __future__ import annotations

import math
import re
import secrets
import time
from collections.abc import Callable
from datetime import UTC, date, datetime
from decimal import Decimal, InvalidOperation
from email.utils import parsedate_to_datetime
from typing import Any

from structa_maestro.contracts.enums import FieldType
from structa_maestro.schema.models import FieldSpec
from structa_maestro.strategies.llm_config import InputBudgetPolicy, RetryPolicy

_UNTRUSTED_TAG_RE = re.compile(r"<(\s*/?\s*untrusted_document\b)", re.IGNORECASE)
_CODE_FENCE_RE = re.compile(
    r"^\s*```(?:json|JSON)?\s*\n(.*?)\n?\s*```\s*$",
    re.DOTALL,
)
_STRUCTURED_OUTPUT_TOKENS: tuple[str, ...] = (
    "response_format",
    "json_schema",
    "structured output",
    "structured_output",
    "additionalproperties",
)
_UNSUPPORTED_HINTS: tuple[str, ...] = (
    "unsupported",
    "not supported",
    "does not support",
    "invalid_request",
    "unknown variant",
    "invalid value",
    "not allowed",
    "strict",
)


def default_rng() -> float:
    """Return a uniform float in [0.0, 1.0) using stdlib secrets (Bandit S311-safe)."""
    return secrets.randbelow(10_000) / 10_000.0


def neutralize_untrusted_delimiters(text: str) -> str:
    """Escape embedded <untrusted_document / </untrusted_document tags inside document text."""
    return _UNTRUSTED_TAG_RE.sub(r"&lt;\1", text)


def apply_input_budget(
    full_text: str,
    budget: InputBudgetPolicy,
) -> tuple[str, bool, int, int]:
    """Apply InputBudgetPolicy to prepared document text.

    Returns ``(retained_text, exceeded, included_chars, total_chars)``.
    When ``exceeded`` is True and ``budget.overflow_policy`` is ``TRUNCATE``,
    ``retained_text`` is deterministically truncated on a clean newline boundary
    when one exists in the second half of the budget, otherwise at ``max_input_chars``.
    """
    total_chars = len(full_text)
    limit = budget.max_input_chars
    if limit is None or total_chars <= limit:
        return full_text, False, total_chars, total_chars

    prefix = full_text[:limit]
    last_nl = prefix.rfind("\n")
    if last_nl >= limit // 2:
        retained = prefix[:last_nl]
    else:
        retained = prefix
    return retained, True, len(retained), total_chars


def parse_retry_after(
    header_value: str | None,
    *,
    now_epoch: float | None = None,
) -> float | None:
    """Parse HTTP Retry-After header (seconds or RFC 7231 HTTP-date) into non-negative seconds."""
    if not header_value or not isinstance(header_value, str):
        return None
    raw = header_value.strip()
    if not raw:
        return None

    # 1. Numeric delay-seconds
    try:
        seconds = float(raw)
    except ValueError:
        seconds = math.nan
    if math.isfinite(seconds):
        return seconds if seconds >= 0.0 else None

    # 2. HTTP-date (RFC 7231)
    try:
        dt = parsedate_to_datetime(raw)
    except (TypeError, ValueError, IndexError):
        return None
    if dt is None:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=UTC)
    now_ts = time.time() if now_epoch is None else now_epoch
    delta = dt.timestamp() - datetime.fromtimestamp(now_ts, tz=UTC).timestamp()
    return max(0.0, delta)


def compute_backoff_delay(
    attempt: int,
    policy: RetryPolicy,
    *,
    retry_after: float | None = None,
    remaining_budget: float | None = None,
    rng: Callable[[], float] | None = None,
) -> float | None:
    """Compute bounded retry delay in seconds, or None if waiting would exceed remaining_budget.

    Per Spec 003 U1: if ``remaining_budget`` is set and a valid parsed ``retry_after``
    meets or exceeds ``remaining_budget``, return ``None`` immediately instead of clamping
    and retrying prematurely.
    """
    if remaining_budget is not None and remaining_budget <= 0.0:
        return None

    if retry_after is not None:
        if remaining_budget is not None and retry_after >= remaining_budget:
            return None
        delay = min(policy.max_backoff_seconds, max(0.0, retry_after))
    else:
        exponent = max(0, attempt - 1)
        base = min(policy.max_backoff_seconds, policy.initial_backoff_seconds * (2**exponent))
        if policy.jitter and base > 0.0:
            draw = (rng or default_rng)()
            clamped_draw = min(1.0, max(0.0, float(draw)))
            delay = base * (0.5 + 0.5 * clamped_draw)
        else:
            delay = base

    if remaining_budget is not None and delay >= remaining_budget:
        return None
    return delay


def extract_json_object_text(raw_content: str) -> tuple[str, bool]:
    """Recover top-level JSON object text from Markdown fences or surrounding prose.

    Returns ``(candidate_json_text, sanitized)`` without mutating any values inside the JSON.
    """
    stripped = raw_content.strip()
    if not stripped:
        return stripped, False

    if stripped.startswith("{") and stripped.endswith("}"):
        return stripped, False

    fenced = _CODE_FENCE_RE.match(stripped)
    if fenced is not None:
        inner = fenced.group(1).strip()
        if inner.startswith("{") and inner.endswith("}"):
            return inner, True
        stripped = inner

    # Locate the first balanced top-level JSON object using a string-aware brace scanner.
    start_idx = stripped.find("{")
    if start_idx == -1:
        return raw_content.strip(), False

    depth = 0
    in_string = False
    escaped = False
    for idx in range(start_idx, len(stripped)):
        ch = stripped[idx]
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
            continue
        if ch == '"':
            in_string = True
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                candidate = stripped[start_idx : idx + 1]
                was_modified = candidate != raw_content.strip()
                return candidate, was_modified

    return raw_content.strip(), False


def coerce_llm_json_value(value: Any, spec: FieldSpec | None) -> Any:
    """Recursively convert clean JSON-wire Decimal/date values without mutating invalid inputs."""
    if value is None or spec is None:
        return value

    if spec.field_type == FieldType.DECIMAL:
        if isinstance(value, Decimal):
            return value
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return Decimal(str(value))
        if isinstance(value, str):
            try:
                return Decimal(value.strip())
            except InvalidOperation:
                return value
        return value

    if spec.field_type == FieldType.DATE:
        if isinstance(value, str):
            try:
                return date.fromisoformat(value.strip())
            except ValueError:
                return value
        return value

    if spec.field_type == FieldType.OBJECT and isinstance(value, dict) and spec.properties:
        return {
            k: coerce_llm_json_value(v, spec.properties.get(k)) if isinstance(k, str) else v
            for k, v in value.items()
        }

    if spec.field_type == FieldType.ARRAY and isinstance(value, list) and spec.items is not None:
        return [coerce_llm_json_value(item, spec.items) for item in value]

    return value


def is_structured_output_unsupported(status_code: int, response_text: str) -> bool:
    """Detect HTTP 400/422 responses specifically rejecting strict json_schema response_format."""
    if status_code not in (400, 422):
        return False
    lowered = response_text.lower()
    if not any(tok in lowered for tok in _STRUCTURED_OUTPUT_TOKENS):
        return False
    return any(hint in lowered for hint in _UNSUPPORTED_HINTS) or "json_schema" in lowered

"""Deterministic closed JSON Schema compiler for strict OpenAI-compatible structured outputs."""

from __future__ import annotations

import re
from dataclasses import dataclass
from datetime import date
from decimal import Decimal
from typing import Any

from structa_maestro.contracts.enums import FieldType
from structa_maestro.schema.models import ExtractionSchema, FieldSpec

_SCHEMA_NAME_RE = re.compile(r"[^a-zA-Z0-9_-]+")


class StrictSchemaIncompatibilityError(ValueError):
    """Raised when an ExtractionSchema cannot be compiled into a closed strict JSON Schema."""


@dataclass(frozen=True, slots=True)
class CompiledOutputSchema:
    """Compiled strict OpenAI-compatible json_schema payload metadata and schema body."""

    name: str
    strict: bool
    schema: dict[str, Any]

    def to_response_format(self) -> dict[str, Any]:
        """Return OpenAI-compatible Chat Completions response_format dictionary."""
        return {
            "type": "json_schema",
            "json_schema": {
                "name": self.name,
                "strict": self.strict,
                "schema": self.schema,
            },
        }


def _sanitize_schema_name(schema_id: str) -> str:
    cleaned = _SCHEMA_NAME_RE.sub("_", schema_id.strip()).strip("_")
    if not cleaned:
        cleaned = "extraction_output"
    return cleaned[:64]


def _has_open_additional_fields(schema: ExtractionSchema) -> str | None:
    if schema.allow_additional_fields:
        return schema.schema_id

    def _walk(spec: FieldSpec, path: str) -> str | None:
        if spec.allow_additional_fields:
            return path
        if spec.properties:
            for key, child in spec.properties.items():
                found = _walk(child, f"{path}.{key}")
                if found is not None:
                    return found
        if spec.items is not None:
            return _walk(spec.items, f"{path}[]")
        return None

    for fname, fspec in schema.fields.items():
        found = _walk(fspec, fname)
        if found is not None:
            return found
    return None


def _to_json_enum_value(val: Any) -> Any:
    if isinstance(val, Decimal):
        return str(val)
    if isinstance(val, date):
        return val.isoformat()
    return val


def _compile_value_schema(spec: FieldSpec, *, allow_null: bool) -> dict[str, Any]:
    """Compile a FieldSpec into a strict-mode-compatible JSON Schema for its value."""
    allowed = spec.constraints.allowed_values

    if spec.field_type == FieldType.STRING:
        node: dict[str, Any] = {"type": ["string", "null"] if allow_null else "string"}
        if allowed is not None:
            vals = [_to_json_enum_value(v) for v in allowed]
            if allow_null and None not in vals:
                vals.append(None)
            node["enum"] = vals
        return node

    if spec.field_type == FieldType.INTEGER:
        node = {"type": ["integer", "null"] if allow_null else "integer"}
        if allowed is not None:
            vals = [_to_json_enum_value(v) for v in allowed]
            if allow_null and None not in vals:
                vals.append(None)
            node["enum"] = vals
        return node

    if spec.field_type == FieldType.BOOLEAN:
        node = {"type": ["boolean", "null"] if allow_null else "boolean"}
        if allowed is not None:
            vals = [_to_json_enum_value(v) for v in allowed]
            if allow_null and None not in vals:
                vals.append(None)
            node["enum"] = vals
        return node

    if spec.field_type == FieldType.DATE:
        node = {
            "type": ["string", "null"] if allow_null else "string",
            "description": "ISO-8601 date string (YYYY-MM-DD).",
        }
        if allowed is not None:
            vals = [_to_json_enum_value(v) for v in allowed]
            if allow_null and None not in vals:
                vals.append(None)
            node["enum"] = vals
        return node

    if spec.field_type == FieldType.DECIMAL:
        if allowed is not None:
            str_vals = [str(v) for v in allowed]
            num_vals: list[float] = []
            for v in allowed:
                if isinstance(v, (int, float, Decimal)) and not isinstance(v, bool):
                    num_vals.append(float(v))
            variants: list[dict[str, Any]] = [{"type": "string", "enum": str_vals}]
            if num_vals:
                variants.append({"type": "number", "enum": num_vals})
            if allow_null:
                variants.append({"type": "null"})
            return {"anyOf": variants}
        variants = [{"type": "string"}, {"type": "number"}]
        if allow_null:
            variants.append({"type": "null"})
        return {"anyOf": variants}

    if spec.field_type == FieldType.OBJECT:
        props = spec.properties or {}
        compiled_props: dict[str, Any] = {}
        req_keys: list[str] = []
        for prop_name, prop_spec in props.items():
            req_keys.append(prop_name)
            prop_nullable = prop_spec.nullable or not prop_spec.required
            compiled_props[prop_name] = _compile_value_schema(prop_spec, allow_null=prop_nullable)
        obj_schema: dict[str, Any] = {
            "type": "object",
            "additionalProperties": False,
            "required": req_keys,
            "properties": compiled_props,
        }
        if allow_null:
            return {"anyOf": [obj_schema, {"type": "null"}]}
        return obj_schema

    if spec.field_type == FieldType.ARRAY:
        item_spec = spec.items
        if item_spec is None:
            item_schema: dict[str, Any] = {"type": ["string", "null"]}
        else:
            item_schema = _compile_value_schema(item_spec, allow_null=item_spec.nullable)
        arr_schema: dict[str, Any] = {"type": "array", "items": item_schema}
        if allow_null:
            return {"anyOf": [arr_schema, {"type": "null"}]}
        return arr_schema

    return {"type": ["string", "null"] if allow_null else "string"}


def _compile_field_envelope(spec: FieldSpec) -> dict[str, Any]:
    """Compile one top-level declared field into its canonical extraction envelope schema."""
    evidence_item: dict[str, Any] = {
        "type": "object",
        "additionalProperties": False,
        "required": ["quote", "relationship"],
        "properties": {
            "quote": {"type": "string"},
            "relationship": {
                "type": "string",
                "enum": ["direct", "inferred", "conflicting"],
            },
        },
    }
    envelope: dict[str, Any] = {
        "type": "object",
        "additionalProperties": False,
        "required": ["presence", "value", "confidence", "ambiguous", "evidence"],
        "properties": {
            "presence": {"type": "string", "enum": ["present", "missing"]},
            # Always allow null on top-level field value because presence="missing" pairs with null.
            "value": _compile_value_schema(spec, allow_null=True),
            "confidence": {"type": ["number", "null"]},
            "ambiguous": {"type": "boolean"},
            "evidence": {"type": "array", "items": evidence_item},
        },
    }
    if spec.description:
        envelope["description"] = spec.description
    return envelope


def compile_extraction_output_schema(schema: ExtractionSchema) -> CompiledOutputSchema:
    """Compile ExtractionSchema into a deterministic closed strict JSON Schema envelope."""
    open_path = _has_open_additional_fields(schema)
    if open_path is not None:
        raise StrictSchemaIncompatibilityError(
            f"ExtractionSchema allows additional fields at {open_path!r}, which cannot be "
            "represented in closed strict json_schema mode."
        )

    field_names = list(schema.fields.keys())
    field_properties = {
        fname: _compile_field_envelope(fspec) for fname, fspec in schema.fields.items()
    }

    record_schema: dict[str, Any] = {
        "type": "object",
        "additionalProperties": False,
        "required": ["fields"],
        "properties": {
            "fields": {
                "type": "object",
                "additionalProperties": False,
                "required": field_names,
                "properties": field_properties,
            }
        },
    }

    root_schema: dict[str, Any] = {
        "type": "object",
        "additionalProperties": False,
        "required": ["records"],
        "properties": {
            "records": {
                "type": "array",
                "items": record_schema,
            }
        },
    }

    return CompiledOutputSchema(
        name=_sanitize_schema_name(schema.schema_id),
        strict=True,
        schema=root_schema,
    )

