"""Immutable in-memory and path-based document input descriptors and sanitizers."""

from __future__ import annotations

import io
from dataclasses import dataclass
from enum import StrEnum
from pathlib import Path
from typing import Any, BinaryIO

from structa_maestro.contracts.enums import DocumentFormat
from structa_maestro.exceptions import ConfigurationError

SUPPORTED_MEDIA_TYPES: dict[str, DocumentFormat] = {
    "text/plain": DocumentFormat.TXT,
    "application/pdf": DocumentFormat.PDF,
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document": DocumentFormat.DOCX,
}


class DocumentInputKind(StrEnum):
    """Mutually exclusive origin kind for a DocumentInput descriptor."""

    PATH = "path"
    BYTES = "bytes"
    TEXT = "text"
    STREAM = "stream"


def sanitize_filename(filename: str | None) -> str | None:
    """Sanitize a caller-supplied filename to a safe basename only.

    - Rejects non-string values and embedded null bytes eagerly with ConfigurationError.
    - Strips POSIX and Windows directory prefixes (e.g. ``/a/b/c.pdf``, ``C:\\a\\b.docx``,
      ``../../etc/passwd``) so directory paths never leak into canonical metadata or logs.
    - Returns ``None`` when no safe basename remains (blank, ``/``, ``.``, ``..``, drive root).
    """
    if filename is None:
        return None
    if not isinstance(filename, str):
        raise ConfigurationError("filename must be a string or None.")
    if "\x00" in filename:
        raise ConfigurationError("filename cannot contain null bytes.")

    normalized = filename.replace("\\", "/").strip()
    if not normalized:
        return None

    parts = [segment.strip() for segment in normalized.split("/") if segment.strip()]
    if not parts:
        return None

    candidate = parts[-1]
    if candidate in (".", "..") or candidate.endswith(":"):
        return None
    return candidate


def normalize_media_type(media_type: str | None) -> str | None:
    """Normalize and validate an optional MIME media_type hint eagerly."""
    if media_type is None:
        return None
    if not isinstance(media_type, str) or not media_type.strip():
        raise ConfigurationError("media_type must be a non-empty MIME type string or None.")
    base_type = media_type.split(";", 1)[0].strip().lower()
    if base_type not in SUPPORTED_MEDIA_TYPES:
        allowed = ", ".join(sorted(SUPPORTED_MEDIA_TYPES))
        raise ConfigurationError(
            f"Unsupported media_type hint {media_type!r}. Supported values: {allowed}."
        )
    return base_type


def _validate_optional_document_id(document_id: str | None) -> str | None:
    if document_id is None:
        return None
    if not isinstance(document_id, str) or not document_id.strip():
        raise ConfigurationError("document_id must be a non-empty string or None.")
    return document_id.strip()


def _validate_binary_stream(stream: Any) -> BinaryIO:
    if stream is None or isinstance(stream, (str, bytes, bytearray, memoryview, io.TextIOBase)):
        raise ConfigurationError("DocumentInput.from_stream requires a readable binary stream.")
    read_fn = getattr(stream, "read", None)
    if not callable(read_fn):
        raise ConfigurationError("DocumentInput.from_stream requires a stream with a read method.")
    if getattr(stream, "closed", False) is True:
        raise ConfigurationError("DocumentInput.from_stream cannot accept a closed stream.")
    readable_fn = getattr(stream, "readable", None)
    if callable(readable_fn):
        try:
            if not readable_fn():
                raise ConfigurationError(
                    "DocumentInput.from_stream requires a readable binary stream."
                )
        except ValueError as exc:
            raise ConfigurationError(
                "DocumentInput.from_stream cannot accept a closed or unusable stream."
            ) from exc
    return stream  # type: ignore[no-any-return]


@dataclass(frozen=True, slots=True, repr=False)
class DocumentInput:
    """Immutable descriptor for path, raw bytes, plain text, or binary stream extraction inputs."""

    kind: DocumentInputKind
    path: Path | None = None
    content: bytes | None = None
    text: str | None = None
    stream: BinaryIO | None = None
    filename: str | None = None
    document_id: str | None = None
    media_type: str | None = None

    def __post_init__(self) -> None:
        if not isinstance(self.kind, DocumentInputKind):
            raise ConfigurationError("DocumentInput.kind must be a DocumentInputKind value.")

        object.__setattr__(self, "document_id", _validate_optional_document_id(self.document_id))
        object.__setattr__(self, "media_type", normalize_media_type(self.media_type))
        sanitized_name = sanitize_filename(self.filename)
        object.__setattr__(self, "filename", sanitized_name)

        if self.kind == DocumentInputKind.PATH:
            if self.content is not None or self.text is not None or self.stream is not None:
                raise ConfigurationError("PATH DocumentInput cannot specify bytes, text, or stream.")
            raw_path: Any = self.path
            if isinstance(raw_path, str):
                if not raw_path.strip():
                    raise ConfigurationError("DocumentInput.path must be a non-empty file path.")
                if "\x00" in raw_path:
                    raise ConfigurationError("DocumentInput.path cannot contain null bytes.")
                resolved_path = Path(raw_path)
            elif isinstance(raw_path, Path):
                path_str = str(raw_path)
                if not path_str.strip():
                    raise ConfigurationError("DocumentInput.path must be a non-empty file path.")
                if "\x00" in path_str:
                    raise ConfigurationError("DocumentInput.path cannot contain null bytes.")
                resolved_path = raw_path
            else:
                raise ConfigurationError("DocumentInput.path must be a str or pathlib.Path.")
            object.__setattr__(self, "path", resolved_path)
            if sanitized_name is None:
                object.__setattr__(self, "filename", sanitize_filename(resolved_path.name))

        elif self.kind == DocumentInputKind.BYTES:
            if self.path is not None or self.text is not None or self.stream is not None:
                raise ConfigurationError("BYTES DocumentInput cannot specify path, text, or stream.")
            raw_content: Any = self.content
            if not isinstance(raw_content, (bytes, bytearray, memoryview)):
                raise ConfigurationError(
                    "DocumentInput.from_bytes requires bytes, bytearray, or memoryview."
                )
            # Snapshot mutable buffers to immutable bytes for thread safety & isolation
            object.__setattr__(self, "content", bytes(raw_content))

        elif self.kind == DocumentInputKind.TEXT:
            if self.path is not None or self.content is not None or self.stream is not None:
                raise ConfigurationError("TEXT DocumentInput cannot specify path, bytes, or stream.")
            if not isinstance(self.text, str):
                raise ConfigurationError("DocumentInput.from_text requires a str payload.")
            if self.media_type is not None and self.media_type != "text/plain":
                raise ConfigurationError(
                    "DocumentInput.from_text only supports media_type='text/plain' or None."
                )

        elif self.kind == DocumentInputKind.STREAM:
            if self.path is not None or self.content is not None or self.text is not None:
                raise ConfigurationError("STREAM DocumentInput cannot specify path, bytes, or text.")
            validated_stream = _validate_binary_stream(self.stream)
            object.__setattr__(self, "stream", validated_stream)

    @classmethod
    def from_path(
        cls,
        path: str | Path,
        *,
        filename: str | None = None,
        document_id: str | None = None,
        media_type: str | None = None,
    ) -> DocumentInput:
        """Create a DocumentInput referencing a filesystem path."""
        return cls(
            kind=DocumentInputKind.PATH,
            path=path,  # type: ignore[arg-type]
            filename=filename,
            document_id=document_id,
            media_type=media_type,
        )

    @classmethod
    def from_bytes(
        cls,
        content: bytes | bytearray | memoryview,
        *,
        filename: str | None = None,
        document_id: str | None = None,
        media_type: str | None = None,
    ) -> DocumentInput:
        """Create a DocumentInput from an immutable snapshot of raw binary content."""
        return cls(
            kind=DocumentInputKind.BYTES,
            content=content,  # type: ignore[arg-type]
            filename=filename,
            document_id=document_id,
            media_type=media_type,
        )

    @classmethod
    def from_text(
        cls,
        text: str,
        *,
        filename: str | None = None,
        document_id: str | None = None,
        media_type: str | None = None,
    ) -> DocumentInput:
        """Create a DocumentInput directly from plain text content."""
        return cls(
            kind=DocumentInputKind.TEXT,
            text=text,
            filename=filename,
            document_id=document_id,
            media_type=media_type,
        )

    @classmethod
    def from_stream(
        cls,
        stream: BinaryIO,
        *,
        filename: str | None = None,
        document_id: str | None = None,
        media_type: str | None = None,
    ) -> DocumentInput:
        """Create a DocumentInput wrapping a readable binary stream (caller owns closing)."""
        return cls(
            kind=DocumentInputKind.STREAM,
            stream=stream,
            filename=filename,
            document_id=document_id,
            media_type=media_type,
        )

    def __repr__(self) -> str:
        """Privacy-safe representation that never discloses raw document content or host paths."""
        parts = [
            f"kind={self.kind.value!r}",
            f"filename={self.filename!r}",
            f"document_id={self.document_id!r}",
            f"media_type={self.media_type!r}",
        ]
        if self.kind == DocumentInputKind.BYTES and self.content is not None:
            parts.append(f"size_bytes={len(self.content)}")
        elif self.kind == DocumentInputKind.TEXT and self.text is not None:
            parts.append(f"size_chars={len(self.text)}")
        return f"DocumentInput({', '.join(parts)})"

"""Safe document input loader enforcing path checks, bounded streams, magic bytes, and limits."""

from __future__ import annotations

import io
import os
import zipfile
from dataclasses import dataclass, field
from pathlib import Path
from typing import BinaryIO
from uuid import uuid4

from structa_maestro.config import DocumentLimits
from structa_maestro.contracts.enums import DocumentFormat, IssueSeverity, PipelineStage
from structa_maestro.contracts.models import DiagnosticIssue, SourceMetadata
from structa_maestro.documents.docx_parser import parse_docx_bytes
from structa_maestro.documents.inputs import (
    SUPPORTED_MEDIA_TYPES,
    DocumentInput,
    DocumentInputKind,
    sanitize_filename,
)
from structa_maestro.documents.models import PreparedDocument
from structa_maestro.documents.pdf_parser import parse_pdf_bytes
from structa_maestro.documents.txt_parser import parse_txt_bytes
from structa_maestro.exceptions import ConfigurationError

_MEDIA_TYPES: dict[DocumentFormat, str] = {
    DocumentFormat.TXT: "text/plain",
    DocumentFormat.PDF: "application/pdf",
    DocumentFormat.DOCX: (
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
    ),
}

_SUPPORTED_EXTENSIONS: frozenset[str] = frozenset({".txt", ".pdf", ".docx"})
_STREAM_CHUNK_BYTES: int = 65_536


@dataclass(frozen=True, slots=True)
class DocumentLoadResult:
    """Result of document loading and text preparation."""

    source: SourceMetadata
    document: PreparedDocument | None = None
    errors: list[DiagnosticIssue] = field(default_factory=list)
    warnings: list[DiagnosticIssue] = field(default_factory=list)


def _detect_format(raw: bytes, extension: str) -> tuple[DocumentFormat | None, str | None]:
    """Detect actual document format from magic bytes rather than blindly trusting extensions."""
    if raw.startswith(b"%PDF-"):
        return DocumentFormat.PDF, None

    if raw.startswith((b"PK\x03\x04", b"PK\x05\x06", b"PK\x07\x08")):
        try:
            with zipfile.ZipFile(io.BytesIO(raw), "r") as zf:
                if "word/document.xml" in zf.namelist():
                    return DocumentFormat.DOCX, None
                return None, "ZIP archive does not contain a DOCX document (word/document.xml)."
        except zipfile.BadZipFile:
            if extension == ".docx":
                return DocumentFormat.DOCX, None
            return None, "Corrupted archive or unsupported binary container."

    if extension == ".pdf":
        return None, "File has .pdf extension but does not start with a valid %PDF header."
    if extension == ".docx":
        return None, "File has .docx extension but is not a valid DOCX archive."
    if extension == ".txt":
        return DocumentFormat.TXT, None

    if extension and extension not in _SUPPORTED_EXTENSIONS:
        return None, f"Unsupported document format extension: {extension!r}."

    # Extensionless payload: attempt plain text only if not binary
    return DocumentFormat.TXT, None


def read_stream_bounded(
    stream: BinaryIO,
    *,
    max_bytes: int,
) -> tuple[bytes | None, DiagnosticIssue | None]:
    """Read binary stream incrementally up to ``max_bytes + 1`` bytes without closing it."""
    if max_bytes < 1:
        raise ConfigurationError("max_bytes must be a positive integer.")

    chunks: list[bytes] = []
    total_read = 0
    cap = max_bytes + 1

    while total_read < cap:
        to_read = min(_STREAM_CHUNK_BYTES, cap - total_read)
        try:
            chunk = stream.read(to_read)
        except (OSError, ValueError):
            return None, DiagnosticIssue(
                code="invalid_input",
                severity=IssueSeverity.ERROR,
                stage=PipelineStage.INPUT,
                message="Failed to read bytes from input binary stream.",
            )

        if chunk is None:
            break
        if isinstance(chunk, str) or not isinstance(chunk, (bytes, bytearray, memoryview)):
            return None, DiagnosticIssue(
                code="invalid_input",
                severity=IssueSeverity.ERROR,
                stage=PipelineStage.INPUT,
                message="Input stream did not yield binary bytes.",
            )

        raw_chunk = bytes(chunk)
        if not raw_chunk:
            break

        chunks.append(raw_chunk)
        total_read += len(raw_chunk)

        if total_read > max_bytes:
            return None, DiagnosticIssue(
                code="resource_limit_exceeded",
                severity=IssueSeverity.ERROR,
                stage=PipelineStage.INPUT,
                message=(
                    f"Input stream exceeds configured max_file_bytes limit ({max_bytes} bytes)."
                ),
            )

    return b"".join(chunks), None


def _load_prepared_from_bytes(
    raw: bytes,
    *,
    doc_id: str,
    safe_filename: str | None,
    limits: DocumentLimits,
    media_type_hint: str | None = None,
) -> DocumentLoadResult:
    """Validate size, sniff magic bytes, reconcile media_type hint, and parse bytes in memory."""
    base_source = SourceMetadata(document_id=doc_id, filename=safe_filename, media_type=None)

    if len(raw) == 0:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="empty_document",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Input document is empty (zero bytes).",
                )
            ],
        )

    if len(raw) > limits.max_file_bytes:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="resource_limit_exceeded",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message=(
                        f"Input document size ({len(raw)} bytes) exceeds configured "
                        f"max_file_bytes limit ({limits.max_file_bytes} bytes)."
                    ),
                )
            ],
        )

    ext = Path(safe_filename).suffix.lower() if safe_filename else ""
    detected_format, detect_err = _detect_format(raw, ext)
    if detected_format is None:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="unsupported_format",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message=detect_err or "Unsupported document format.",
                )
            ],
        )

    if media_type_hint is not None:
        expected_format = SUPPORTED_MEDIA_TYPES.get(media_type_hint)
        if expected_format is not None and detected_format != expected_format:
            return DocumentLoadResult(
                source=base_source,
                errors=[
                    DiagnosticIssue(
                        code="unsupported_format",
                        severity=IssueSeverity.ERROR,
                        stage=PipelineStage.INPUT,
                        message=(
                            f"Caller media_type hint {media_type_hint!r} does not match "
                            f"detected content format {_MEDIA_TYPES[detected_format]!r}."
                        ),
                    )
                ],
            )

    warnings: list[DiagnosticIssue] = []
    if ext and ext in _SUPPORTED_EXTENSIONS and ext != f".{detected_format.value}":
        warnings.append(
            DiagnosticIssue(
                code="extension_mismatch",
                severity=IssueSeverity.WARNING,
                stage=PipelineStage.INPUT,
                message=(
                    f"File extension {ext!r} does not match detected content format "
                    f"{detected_format.value!r}; processed using detected format."
                ),
            )
        )

    source = SourceMetadata(
        document_id=doc_id,
        filename=safe_filename,
        media_type=_MEDIA_TYPES[detected_format],
    )

    if detected_format == DocumentFormat.TXT:
        parsed = parse_txt_bytes(raw, source, limits)
    elif detected_format == DocumentFormat.PDF:
        parsed = parse_pdf_bytes(raw, source, limits)
    else:
        parsed = parse_docx_bytes(raw, source, limits)

    return DocumentLoadResult(
        source=source,
        document=parsed.document,
        errors=list(parsed.errors),
        warnings=warnings + list(parsed.warnings),
    )


def load_document(
    path: str | Path,
    *,
    limits: DocumentLimits | None = None,
    document_id: str | None = None,
    filename_override: str | None = None,
    media_type_hint: str | None = None,
) -> DocumentLoadResult:
    """Inspect, validate, and parse a single TXT, text-based PDF, or DOCX document safely."""
    active_limits = limits or DocumentLimits()
    doc_path = Path(path)
    doc_id = document_id.strip() if document_id and document_id.strip() else str(uuid4())
    # Basename only to avoid leaking local host paths in canonical metadata
    safe_filename = (
        filename_override
        if filename_override is not None
        else (doc_path.name if doc_path.name else None)
    )
    base_source = SourceMetadata(document_id=doc_id, filename=safe_filename, media_type=None)

    if "\x00" in str(path):
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="invalid_input",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Document path contains invalid null byte.",
                )
            ],
        )

    try:
        exists = doc_path.exists()
    except OSError:
        exists = False

    if not exists:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="file_not_found",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Input document path does not exist.",
                )
            ],
        )

    if doc_path.is_dir():
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="invalid_input",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Input path refers to a directory rather than a regular file.",
                )
            ],
        )

    if not doc_path.is_file():
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="invalid_input",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Input path is not a regular readable file.",
                )
            ],
        )

    if not os.access(doc_path, os.R_OK):
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="permission_denied",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Input document cannot be read due to file permissions.",
                )
            ],
        )

    try:
        file_size = doc_path.stat().st_size
    except OSError:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="invalid_input",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Unable to inspect input document file metadata.",
                )
            ],
        )

    if file_size == 0:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="empty_document",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Input document is empty (zero bytes).",
                )
            ],
        )

    if file_size > active_limits.max_file_bytes:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="resource_limit_exceeded",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message=(
                        f"Input document size ({file_size} bytes) exceeds configured "
                        f"max_file_bytes limit ({active_limits.max_file_bytes} bytes)."
                    ),
                )
            ],
        )

    try:
        raw = doc_path.read_bytes()
    except PermissionError:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="permission_denied",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Permission denied while reading input document.",
                )
            ],
        )
    except OSError:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="invalid_input",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Failed to read input document bytes.",
                )
            ],
        )

    if len(raw) > active_limits.max_file_bytes:
        return DocumentLoadResult(
            source=base_source,
            errors=[
                DiagnosticIssue(
                    code="resource_limit_exceeded",
                    severity=IssueSeverity.ERROR,
                    stage=PipelineStage.INPUT,
                    message="Input document grew beyond configured max_file_bytes while reading.",
                )
            ],
        )

    return _load_prepared_from_bytes(
        raw,
        doc_id=doc_id,
        safe_filename=safe_filename,
        limits=active_limits,
        media_type_hint=media_type_hint,
    )


def load_document_input(
    doc_input: DocumentInput,
    *,
    limits: DocumentLimits | None = None,
    document_id: str | None = None,
) -> DocumentLoadResult:
    """Load and prepare any DocumentInput (path, bytes, plain text, or binary stream) safely."""
    if not isinstance(doc_input, DocumentInput):
        raise ConfigurationError("doc_input must be a DocumentInput instance.")

    active_limits = limits or DocumentLimits()
    if document_id is not None:
        if not isinstance(document_id, str) or not document_id.strip():
            raise ConfigurationError("document_id must be a non-empty string or None.")
        resolved_doc_id = document_id.strip()
    elif doc_input.document_id is not None:
        resolved_doc_id = doc_input.document_id
    else:
        resolved_doc_id = str(uuid4())

    safe_filename = sanitize_filename(doc_input.filename)

    if doc_input.kind == DocumentInputKind.PATH:
        if doc_input.path is None:
            raise ConfigurationError("PATH DocumentInput is missing a path.")
        return load_document(
            doc_input.path,
            limits=active_limits,
            document_id=resolved_doc_id,
            filename_override=safe_filename,
            media_type_hint=doc_input.media_type,
        )

    if doc_input.kind == DocumentInputKind.BYTES:
        raw_bytes = doc_input.content if doc_input.content is not None else b""
        return _load_prepared_from_bytes(
            raw_bytes,
            doc_id=resolved_doc_id,
            safe_filename=safe_filename,
            limits=active_limits,
            media_type_hint=doc_input.media_type,
        )

    if doc_input.kind == DocumentInputKind.TEXT:
        raw_text_bytes = (doc_input.text or "").encode("utf-8")
        base_source = SourceMetadata(
            document_id=resolved_doc_id,
            filename=safe_filename,
            media_type=_MEDIA_TYPES[DocumentFormat.TXT],
        )
        if len(raw_text_bytes) == 0:
            return DocumentLoadResult(
                source=SourceMetadata(
                    document_id=resolved_doc_id,
                    filename=safe_filename,
                    media_type=None,
                ),
                errors=[
                    DiagnosticIssue(
                        code="empty_document",
                        severity=IssueSeverity.ERROR,
                        stage=PipelineStage.INPUT,
                        message="Input plain-text document is empty.",
                    )
                ],
            )
        if len(raw_text_bytes) > active_limits.max_file_bytes:
            return DocumentLoadResult(
                source=SourceMetadata(
                    document_id=resolved_doc_id,
                    filename=safe_filename,
                    media_type=None,
                ),
                errors=[
                    DiagnosticIssue(
                        code="resource_limit_exceeded",
                        severity=IssueSeverity.ERROR,
                        stage=PipelineStage.INPUT,
                        message=(
                            f"Input plain-text size ({len(raw_text_bytes)} bytes) exceeds "
                            f"configured max_file_bytes limit ({active_limits.max_file_bytes} "
                            "bytes)."
                        ),
                    )
                ],
            )
        parsed = parse_txt_bytes(raw_text_bytes, base_source, active_limits)
        return DocumentLoadResult(
            source=base_source,
            document=parsed.document,
            errors=list(parsed.errors),
            warnings=list(parsed.warnings),
        )

    # DocumentInputKind.STREAM
    if doc_input.stream is None:
        raise ConfigurationError("STREAM DocumentInput is missing a binary stream.")
    raw_stream_bytes, read_err = read_stream_bounded(
        doc_input.stream,
        max_bytes=active_limits.max_file_bytes,
    )
    if read_err is not None or raw_stream_bytes is None:
        err_issue = read_err or DiagnosticIssue(
            code="invalid_input",
            severity=IssueSeverity.ERROR,
            stage=PipelineStage.INPUT,
            message="Failed to read input binary stream.",
        )
        return DocumentLoadResult(
            source=SourceMetadata(
                document_id=resolved_doc_id,
                filename=safe_filename,
                media_type=None,
            ),
            errors=[err_issue],
        )

    return _load_prepared_from_bytes(
        raw_stream_bytes,
        doc_id=resolved_doc_id,
        safe_filename=safe_filename,
        limits=active_limits,
        media_type_hint=doc_input.media_type,
    )

"""Stateless, in-process batch document extraction models, scheduler, and directory discovery."""

from __future__ import annotations

import json
import os
import time
from collections.abc import Callable, Sequence
from concurrent.futures import FIRST_COMPLETED, Future, ThreadPoolExecutor, wait
from dataclasses import dataclass
from pathlib import Path
from typing import Any
from uuid import uuid4

from structa_maestro.config import DocumentLimits
from structa_maestro.contracts.enums import IssueSeverity, PipelineStage, ProcessingStatus, ValidationStatus
from structa_maestro.contracts.models import (
    DiagnosticIssue,
    ExtractionResult,
    SchemaMetadata,
    SourceMetadata,
)
from structa_maestro.documents.inputs import DocumentInput, DocumentInputKind
from structa_maestro.documents.loader import DocumentLoadResult, read_stream_bounded
from structa_maestro.exceptions import ConfigurationError

MAX_BATCH_WORKERS = 32
SUPPORTED_BATCH_EXTENSIONS: frozenset[str] = frozenset({".txt", ".pdf", ".docx"})


@dataclass(frozen=True, slots=True)
class BatchDocumentInput:
    """Immutable per-document batch input pairing a file path with an optional document ID."""

    path: Path
    document_id: str | None = None

    def __post_init__(self) -> None:
        raw_path: Any = self.path
        if isinstance(raw_path, str):
            if not raw_path.strip():
                raise ConfigurationError("BatchDocumentInput.path must be a non-empty file path.")
            object.__setattr__(self, "path", Path(raw_path))
        elif isinstance(raw_path, Path):
            if not str(raw_path).strip():
                raise ConfigurationError("BatchDocumentInput.path must be a non-empty file path.")
        else:
            raise ConfigurationError("BatchDocumentInput.path must be a str or pathlib.Path.")

        if self.document_id is not None:
            if not isinstance(self.document_id, str) or not self.document_id.strip():
                raise ConfigurationError(
                    "BatchDocumentInput.document_id must be a non-empty string or None."
                )
            object.__setattr__(self, "document_id", self.document_id.strip())


@dataclass(frozen=True, slots=True)
class _PreparedBatchItem:
    """Internal normalized batch item holding a DocumentInput and optional pre-captured error."""

    document_input: DocumentInput
    preloaded_error: DocumentLoadResult | None = None


@dataclass(frozen=True, slots=True)
class BatchOptions:
    """Immutable in-process batch execution options validated eagerly on construction."""

    max_workers: int = 1
    fail_fast: bool = False

    def __post_init__(self) -> None:
        if (
            isinstance(self.max_workers, bool)
            or not isinstance(self.max_workers, int)
            or self.max_workers < 1
            or self.max_workers > MAX_BATCH_WORKERS
        ):
            raise ConfigurationError(
                f"BatchOptions.max_workers must be an integer between 1 and {MAX_BATCH_WORKERS}."
            )
        if not isinstance(self.fail_fast, bool):
            raise ConfigurationError("BatchOptions.fail_fast must be a boolean.")


@dataclass(frozen=True, slots=True)
class BatchSummary:
    """Immutable aggregate processing and validation statistics for a batch extraction run."""

    total_documents: int
    processed_documents: int
    skipped_documents: int
    completed_count: int
    partial_count: int
    failed_count: int
    valid_count: int
    invalid_count: int
    not_validated_count: int
    aborted_early: bool
    elapsed_ms: float

    def to_dict(self) -> dict[str, Any]:
        """Return a JSON-safe dictionary representation of the batch summary."""
        return {
            "total_documents": self.total_documents,
            "processed_documents": self.processed_documents,
            "skipped_documents": self.skipped_documents,
            "completed_count": self.completed_count,
            "partial_count": self.partial_count,
            "failed_count": self.failed_count,
            "valid_count": self.valid_count,
            "invalid_count": self.invalid_count,
            "not_validated_count": self.not_validated_count,
            "aborted_early": self.aborted_early,
            "elapsed_ms": self.elapsed_ms,
        }

    def to_json(self, *, indent: int | None = None) -> str:
        """Serialize the batch summary to JSON."""
        return json.dumps(self.to_dict(), indent=indent, ensure_ascii=False)


@dataclass(frozen=True, slots=True)
class BatchExtractionResult:
    """Immutable ordered batch container holding per-document Contract v1.0 results and summary."""

    batch_id: str
    schema_metadata: SchemaMetadata
    results: tuple[ExtractionResult, ...]
    summary: BatchSummary

    def to_jsonl(self) -> str:
        """Serialize processed Canonical Output Record Contract v1.0 results as JSON Lines."""
        if not self.results:
            return ""
        return "\n".join(res.to_json(indent=None) for res in self.results) + "\n"

    def to_dict(self) -> dict[str, Any]:
        """Return a JSON-safe batch envelope preserving Contract v1.0 for every item."""
        return {
            "batch_id": self.batch_id,
            "schema": {
                "schema_id": self.schema_metadata.schema_id,
                "schema_version": self.schema_metadata.schema_version,
            },
            "summary": self.summary.to_dict(),
            "results": [res.to_dict() for res in self.results],
        }

    def to_json(self, *, indent: int | None = None) -> str:
        """Serialize the batch envelope to JSON."""
        return json.dumps(self.to_dict(), indent=indent, ensure_ascii=False)


def normalize_batch_inputs(
    documents: Sequence[str | Path | BatchDocumentInput | DocumentInput],
) -> tuple[DocumentInput, ...]:
    """Eagerly validate and normalize batch input descriptors before opening any file or stream."""
    if isinstance(documents, (str, bytes, bytearray)) or not isinstance(documents, Sequence):
        raise ConfigurationError(
            "Batch documents must be a non-empty sequence of paths, BatchDocumentInput, "
            "or DocumentInput items."
        )
    if len(documents) == 0:
        raise ConfigurationError("Batch documents collection cannot be empty.")

    normalized: list[DocumentInput] = []
    seen_doc_ids: set[str] = set()
    for idx, item in enumerate(documents):
        if isinstance(item, DocumentInput):
            desc = item
        elif isinstance(item, BatchDocumentInput):
            desc = DocumentInput.from_path(item.path, document_id=item.document_id)
        elif isinstance(item, (str, Path)):
            if isinstance(item, str) and not item.strip():
                raise ConfigurationError(f"Batch document at index {idx} cannot be blank.")
            desc = DocumentInput.from_path(item)
        else:
            raise ConfigurationError(
                f"Batch document at index {idx} must be str, pathlib.Path, "
                "BatchDocumentInput, or DocumentInput."
            )

        if desc.document_id is not None:
            if desc.document_id in seen_doc_ids:
                raise ConfigurationError(
                    f"Duplicate caller-supplied document_id in batch: {desc.document_id!r}"
                )
            seen_doc_ids.add(desc.document_id)
        normalized.append(desc)

    return tuple(normalized)


def prepare_batch_items(
    inputs: tuple[DocumentInput, ...],
    *,
    limits: DocumentLimits,
    max_workers: int,
) -> tuple[_PreparedBatchItem, ...]:
    """Prepare normalized batch items, safely pre-materializing streams for concurrent workers."""
    if max_workers <= 1:
        return tuple(_PreparedBatchItem(document_input=item) for item in inputs)

    prepared: list[_PreparedBatchItem] = []
    for item in inputs:
        if item.kind != DocumentInputKind.STREAM:
            prepared.append(_PreparedBatchItem(document_input=item))
            continue

        if item.stream is None:
            raise ConfigurationError("STREAM DocumentInput is missing a binary stream.")

        raw_bytes, read_err = read_stream_bounded(item.stream, max_bytes=limits.max_file_bytes)
        if read_err is not None or raw_bytes is None:
            doc_id = item.document_id or str(uuid4())
            err_issue = read_err or DiagnosticIssue(
                code="invalid_input",
                severity=IssueSeverity.ERROR,
                stage=PipelineStage.INPUT,
                message="Failed to read input binary stream.",
            )
            failed_load = DocumentLoadResult(
                source=SourceMetadata(
                    document_id=doc_id,
                    filename=item.filename,
                    media_type=None,
                ),
                errors=[err_issue],
            )
            prepared.append(
                _PreparedBatchItem(document_input=item, preloaded_error=failed_load)
            )
        else:
            snapshot = DocumentInput.from_bytes(
                raw_bytes,
                filename=item.filename,
                document_id=item.document_id,
                media_type=item.media_type,
            )
            prepared.append(_PreparedBatchItem(document_input=snapshot))

    return tuple(prepared)


def _compute_summary(
    *,
    total_documents: int,
    results: Sequence[ExtractionResult],
    aborted_early: bool,
    elapsed_ms: float,
) -> BatchSummary:
    completed = sum(1 for r in results if r.status == ProcessingStatus.COMPLETED)
    partial = sum(1 for r in results if r.status == ProcessingStatus.PARTIAL)
    failed = sum(1 for r in results if r.status == ProcessingStatus.FAILED)

    valid = sum(1 for r in results if r.validation.status == ValidationStatus.VALID)
    invalid = sum(1 for r in results if r.validation.status == ValidationStatus.INVALID)
    not_validated = sum(1 for r in results if r.validation.status == ValidationStatus.NOT_VALIDATED)

    processed = len(results)
    return BatchSummary(
        total_documents=total_documents,
        processed_documents=processed,
        skipped_documents=total_documents - processed,
        completed_count=completed,
        partial_count=partial,
        failed_count=failed,
        valid_count=valid,
        invalid_count=invalid,
        not_validated_count=not_validated,
        aborted_early=aborted_early,
        elapsed_ms=round(max(0.0, elapsed_ms), 3),
    )


def run_batch_extraction(
    *,
    inputs: tuple[_PreparedBatchItem, ...],
    schema_metadata: SchemaMetadata,
    options: BatchOptions,
    extract_one: Callable[[_PreparedBatchItem], ExtractionResult],
) -> BatchExtractionResult:
    """Execute stateless sequential or bounded concurrent batch extraction in exact input order."""
    started = time.perf_counter()
    total = len(inputs)
    aborted_early = False

    if options.max_workers == 1:
        ordered_results: list[ExtractionResult] = []
        for idx, doc_input in enumerate(inputs):
            res = extract_one(doc_input)
            ordered_results.append(res)
            if options.fail_fast and res.status == ProcessingStatus.FAILED and idx < total - 1:
                aborted_early = True
                break
        final_results = tuple(ordered_results)
    else:
        completed_by_idx: dict[int, ExtractionResult] = {}
        worker_count = min(options.max_workers, total)
        next_idx = 0
        stop_submitting = False

        with ThreadPoolExecutor(max_workers=worker_count) as pool:
            in_flight: dict[Future[ExtractionResult], int] = {}

            while next_idx < total and len(in_flight) < worker_count:
                fut = pool.submit(extract_one, inputs[next_idx])
                in_flight[fut] = next_idx
                next_idx += 1

            while in_flight:
                done, _ = wait(in_flight.keys(), return_when=FIRST_COMPLETED)
                for fut in done:
                    idx = in_flight.pop(fut)
                    res = fut.result()
                    completed_by_idx[idx] = res
                    if options.fail_fast and res.status == ProcessingStatus.FAILED:
                        stop_submitting = True

                while not stop_submitting and next_idx < total and len(in_flight) < worker_count:
                    fut = pool.submit(extract_one, inputs[next_idx])
                    in_flight[fut] = next_idx
                    next_idx += 1

        aborted_early = stop_submitting and len(completed_by_idx) < total
        final_results = tuple(completed_by_idx[i] for i in sorted(completed_by_idx))

    elapsed_ms = (time.perf_counter() - started) * 1000.0
    summary = _compute_summary(
        total_documents=total,
        results=final_results,
        aborted_early=aborted_early,
        elapsed_ms=elapsed_ms,
    )
    return BatchExtractionResult(
        batch_id=str(uuid4()),
        schema_metadata=schema_metadata,
        results=final_results,
        summary=summary,
    )


def discover_batch_documents(
    inputs: Sequence[str | Path],
    *,
    recursive: bool = False,
) -> list[Path]:
    """Deterministically resolve CLI file and directory inputs without symlink cycles.

    - Existing directories are scanned lexicographically (non-recursively by default, or
      recursively with ``followlinks=False``), ignoring hidden dotfiles/directories and broken
      symlinks, and keeping files with supported extensions (``.txt``, ``.pdf``, ``.docx``).
    - Explicitly named file paths (including nonexistent paths) are preserved in caller order.
    """
    discovered: list[Path] = []
    for raw in inputs:
        path = Path(raw)
        if path.is_dir():
            dir_files: list[Path] = []
            if recursive:
                for root_str, dirnames, filenames in os.walk(path, followlinks=False):
                    # Prune hidden directories & symlinked subdirectories in deterministic order
                    root_path = Path(root_str)
                    dirnames[:] = sorted(
                        d
                        for d in dirnames
                        if not d.startswith(".") and not (root_path / d).is_symlink()
                    )
                    for fname in sorted(filenames):
                        if fname.startswith("."):
                            continue
                        candidate = root_path / fname
                        if candidate.is_symlink() and not candidate.exists():
                            continue
                        if (
                            candidate.is_file()
                            and candidate.suffix.lower() in SUPPORTED_BATCH_EXTENSIONS
                        ):
                            dir_files.append(candidate)
            else:
                for entry in sorted(path.iterdir(), key=lambda p: p.name):
                    if entry.name.startswith("."):
                        continue
                    if entry.is_symlink() and not entry.exists():
                        continue
                    if entry.is_file() and entry.suffix.lower() in SUPPORTED_BATCH_EXTENSIONS:
                        dir_files.append(entry)
            dir_files.sort(key=lambda p: p.as_posix())
            discovered.extend(dir_files)
        else:
            discovered.append(path)
    return discovered

"""Main ExtractionEngine and extract() orchestration pipeline with stage failure isolation."""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from pathlib import Path
from typing import Any

from structa_maestro.batch import (
    BatchDocumentInput,
    BatchExtractionResult,
    BatchOptions,
    _PreparedBatchItem,
    normalize_batch_inputs,
    prepare_batch_items,
    run_batch_extraction,
)
from structa_maestro.builder.result_builder import ResultBuilder
from structa_maestro.config import DocumentLimits, get_logger, sanitize_message
from structa_maestro.contracts.enums import IssueSeverity, PipelineStage
from structa_maestro.contracts.models import DiagnosticIssue, ExtractionResult, SchemaMetadata
from structa_maestro.documents.inputs import DocumentInput
from structa_maestro.documents.loader import (
    DocumentLoadResult,
    load_document,
    load_document_input,
)
from structa_maestro.exceptions import ConfigurationError, SchemaDefinitionError
from structa_maestro.schema.models import ExtractionSchema
from structa_maestro.strategies.base import ExtractionStrategy

_logger = get_logger(__name__)


def _coerce_schema(schema: ExtractionSchema | Mapping[str, Any]) -> ExtractionSchema:
    if isinstance(schema, ExtractionSchema):
        return schema
    if isinstance(schema, Mapping):
        return ExtractionSchema.from_dict(schema)
    raise SchemaDefinitionError(
        f"Expected ExtractionSchema or mapping schema definition, got {type(schema).__name__}."
    )


class ExtractionEngine:
    """Stateless structured extraction orchestrator isolating all operational stages."""

    def __init__(
        self,
        strategy: ExtractionStrategy,
        *,
        limits: DocumentLimits | None = None,
        result_builder: ResultBuilder | None = None,
    ) -> None:
        if not isinstance(strategy, ExtractionStrategy):
            raise ConfigurationError(
                "ExtractionEngine requires a strategy implementing ExtractionStrategy."
            )
        if limits is not None and not isinstance(limits, DocumentLimits):
            raise ConfigurationError("limits must be a DocumentLimits instance or None.")
        self._strategy = strategy
        self._limits = limits or DocumentLimits()
        self._builder = result_builder or ResultBuilder()

    @property
    def limits(self) -> DocumentLimits:
        """Configured document safety limits."""
        return self._limits

    def _extract_from_load_result(
        self,
        load_result: DocumentLoadResult,
        parsed_schema: ExtractionSchema,
    ) -> ExtractionResult:
        """Run strategy + canonical assembly from an already-loaded DocumentLoadResult."""
        if load_result.document is None:
            _logger.debug(
                "Document loading failed for document_id=%s with %d error(s)",
                load_result.source.document_id,
                len(load_result.errors),
            )
            return self._builder.build_failed(
                schema=parsed_schema,
                source=load_result.source,
                errors=load_result.errors
                or [
                    DiagnosticIssue(
                        code="document_processing_failed",
                        severity=IssueSeverity.ERROR,
                        stage=PipelineStage.DOCUMENT_PROCESSING,
                        message="Document processing failed without producing prepared text.",
                    )
                ],
                warnings=load_result.warnings,
            )

        # 3. Extraction strategy execution (fully isolated; never crashes consumer)
        try:
            strategy_output = self._strategy.extract_raw(load_result.document, parsed_schema)
        except Exception as exc:
            safe_msg = sanitize_message(
                f"Extraction strategy '{self._strategy.name}' failed: {type(exc).__name__}"
            )
            _logger.debug(
                "Strategy error for document_id=%s: %s", load_result.source.document_id, safe_msg
            )
            return self._builder.build_failed(
                schema=parsed_schema,
                source=load_result.source,
                errors=[
                    DiagnosticIssue(
                        code="extraction_strategy_error",
                        severity=IssueSeverity.ERROR,
                        stage=PipelineStage.EXTRACTION,
                        message=safe_msg,
                    )
                ],
                warnings=load_result.warnings,
            )

        # 4. Provenance, confidence, deterministic validation & canonical assembly
        try:
            return self._builder.build(
                document=load_result.document,
                schema=parsed_schema,
                strategy_output=strategy_output,
                document_warnings=load_result.warnings,
            )
        except Exception as exc:
            safe_msg = sanitize_message(
                f"Canonical result assembly failed unexpectedly: {type(exc).__name__}"
            )
            return self._builder.build_failed(
                schema=parsed_schema,
                source=load_result.source,
                errors=[
                    DiagnosticIssue(
                        code="result_assembly_error",
                        severity=IssueSeverity.ERROR,
                        stage=PipelineStage.VALIDATION,
                        message=safe_msg,
                    )
                ],
                warnings=load_result.warnings,
            )

    def extract(
        self,
        document: str | Path | DocumentInput,
        schema: ExtractionSchema | Mapping[str, Any],
        *,
        document_id: str | None = None,
    ) -> ExtractionResult:
        """Extract validated canonical structured records from a path or DocumentInput.

        Failure boundary:
        - Invalid schema, engine configuration, or blank call-level document_id alongside a
          DocumentInput raises SchemaDefinitionError / ConfigurationError eagerly.
        - All document input, parsing, extraction, provenance, and validation failures return
          a canonical ExtractionResult with status='failed' or status='partial'.
        """
        # 1. Pre-flight schema validation (raises SchemaDefinitionError on caller mistake)
        parsed_schema = _coerce_schema(schema)

        if isinstance(document, DocumentInput):
            load_result = load_document_input(
                document,
                limits=self._limits,
                document_id=document_id,
            )
            return self._extract_from_load_result(load_result, parsed_schema)

        if not isinstance(document, (str, Path)):
            return self._builder.build_failed(
                schema=parsed_schema,
                source=None,
                errors=[
                    DiagnosticIssue(
                        code="invalid_input",
                        severity=IssueSeverity.ERROR,
                        stage=PipelineStage.INPUT,
                        message=(
                            "Document input must be a file path (str or pathlib.Path) "
                            "or a DocumentInput instance."
                        ),
                    )
                ],
            )

        # 2. Safe document loading & text preparation
        load_result = load_document(document, limits=self._limits, document_id=document_id)
        return self._extract_from_load_result(load_result, parsed_schema)

    def extract_batch(
        self,
        documents: Sequence[str | Path | BatchDocumentInput | DocumentInput],
        schema: ExtractionSchema | Mapping[str, Any],
        *,
        options: BatchOptions | None = None,
    ) -> BatchExtractionResult:
        """Statelessly extract a mixed collection of paths and in-memory documents in order."""
        parsed_schema = _coerce_schema(schema)
        resolved_options = options if options is not None else BatchOptions()
        if not isinstance(resolved_options, BatchOptions):
            raise ConfigurationError("options must be a BatchOptions instance or None.")
        normalized_inputs = normalize_batch_inputs(documents)
        prepared_items = prepare_batch_items(
            normalized_inputs,
            limits=self._limits,
            max_workers=resolved_options.max_workers,
        )
        schema_meta = SchemaMetadata(
            schema_id=parsed_schema.schema_id,
            schema_version=parsed_schema.schema_version,
        )

        def _extract_one(item: _PreparedBatchItem) -> ExtractionResult:
            if item.preloaded_error is not None:
                return self._extract_from_load_result(item.preloaded_error, parsed_schema)
            return self.extract(item.document_input, parsed_schema)

        return run_batch_extraction(
            inputs=prepared_items,
            schema_metadata=schema_meta,
            options=resolved_options,
            extract_one=_extract_one,
        )


def extract(
    document: str | Path | DocumentInput,
    schema: ExtractionSchema | Mapping[str, Any],
    *,
    strategy: ExtractionStrategy,
    limits: DocumentLimits | None = None,
    document_id: str | None = None,
) -> ExtractionResult:
    """Convenience functional entry point delegating directly to ExtractionEngine."""
    engine = ExtractionEngine(strategy=strategy, limits=limits)
    return engine.extract(document, schema, document_id=document_id)


def extract_batch(
    documents: Sequence[str | Path | BatchDocumentInput | DocumentInput],
    schema: ExtractionSchema | Mapping[str, Any],
    *,
    strategy: ExtractionStrategy,
    limits: DocumentLimits | None = None,
    options: BatchOptions | None = None,
) -> BatchExtractionResult:
    """Convenience functional batch entry point delegating directly to ExtractionEngine."""
    engine = ExtractionEngine(strategy=strategy, limits=limits)
    return engine.extract_batch(documents, schema, options=options)

